/* ==========================================================================
   StreamWave Entertainment - Responsive Media Platform Stylesheet
   Dark Graphite Theme with Restrained Red Accent
   ========================================================================== */

:root {
    --bg-base: #121214;
    --bg-surface: #18181c;
    --bg-elevated: #222228;
    --bg-hover: #2e2e36;

    --border-color: #2e2e38;
    --border-focus: #e50914;

    --text-primary: #f4f4f6;
    --text-secondary: #a0a0ab;
    --text-muted: #6e6e7a;

    --accent-red: #e50914;
    --accent-red-hover: #b80710;
    --accent-red-subtle: rgba(229, 9, 20, 0.15);

    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --radius-sm: 4px;
    --radius-md: 6px;

    --shadow-card: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-dialog: 0 16px 32px rgba(0, 0, 0, 0.7);
}

/* Base Resets */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    overflow-x: hidden;
    scroll-behavior: smooth;
}

body {
    background-color: var(--bg-base);
    color: var(--text-primary);
    font-family: var(--font-family);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    padding-bottom: 110px; /* Space so fixed audio player never obscures footer */
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
}

button, input, select {
    font-family: inherit;
    font-size: inherit;
}

/* Accessibility Focus Visible */
*:focus-visible {
    outline: 2px solid var(--accent-red);
    outline-offset: 2px;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

/* Navigation Bar */
.navbar {
    background-color: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav-container {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0.75rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-weight: 800;
    font-size: 1.2rem;
    letter-spacing: -0.02em;
    color: var(--text-primary);
}

.logo-symbol {
    color: var(--accent-red);
    font-size: 1rem;
}

.logo-accent {
    color: var(--accent-red);
}

.nav-links {
    display: flex;
    gap: 1.25rem;
    align-items: center;
}

.nav-link {
    color: var(--text-secondary);
    font-size: 0.875rem;
    font-weight: 500;
    transition: color 0.15s ease;
}

.nav-link:hover, .nav-link.active {
    color: var(--text-primary);
}

.developer-link {
    color: var(--accent-red);
    font-weight: 600;
    font-size: 0.8rem;
    background-color: var(--accent-red-subtle);
    padding: 0.2rem 0.55rem;
    border-radius: var(--radius-sm);
    border: 1px solid rgba(229, 9, 20, 0.3);
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.developer-link:hover {
    background-color: rgba(229, 9, 20, 0.25);
    color: #ffffff;
}

.ext-icon {
    font-size: 0.75rem;
}

.serverless-badge-sm {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
