    background-color: #10b981;
    border-radius: 50%;
}

/* Main Container */
.main-content {
    max-width: 1240px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    flex: 1;
}

/* Hero / Featured Section */
.hero-section {
