}

/* UI States */
.state-view {
    text-align: center;
    padding: 3rem 1rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
}

.state-icon {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

