    font-size: 0.875rem;
    margin-bottom: 1rem;
}

.spinner {
    width: 32px;
    height: 32px;
    border: 3px solid var(--border-color);
    border-top-color: var(--accent-red);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 1rem auto;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Media Cards Grid - Responsive Breakdown */
.media-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
}

@media (max-width: 1199px) {
    .media-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 899px) {
    .media-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 599px) {
    .media-grid {
        grid-template-columns: repeat(1, 1fr);
    }
}

/* Media Card Styling */
.media-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    height: 100%;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.media-card:hover {
    transform: translateY(-2px);
    border-color: var(--text-muted);
}

.card-thumb-wrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    background-color: var(--bg-elevated);
    overflow: hidden;
    cursor: pointer;
}

.card-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.25s ease;
}

.card-thumb-wrapper:hover .card-thumb {
    transform: scale(1.04);
}

.card-badge {
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
    background-color: rgba(18, 18, 20, 0.9);
    border: 1px solid var(--border-color);
    color: var(--accent-red);
    font-size: 0.675rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.125rem 0.45rem;
    border-radius: var(--radius-sm);
    letter-spacing: 0.04em;
}

.tech-sample-tag {
    position: absolute;
    bottom: 0.5rem;
    right: 0.5rem;
    background-color: rgba(18, 18, 20, 0.85);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.625rem;
    padding: 0.1rem 0.35rem;
    border-radius: var(--radius-sm);
}

.card-content {
    padding: 0.95rem;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.card-title {
    font-size: 0.975rem;
    font-weight: 700;
    line-height: 1.35;
    margin-bottom: 0.25rem;
    color: var(--text-primary);
    cursor: pointer;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    max-height: 2.7em;
}

.card-title:hover {
    color: var(--accent-red);
}

.card-subtitle {
    color: var(--text-secondary);
    font-size: 0.825rem;
    margin-bottom: 0.4rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.card-meta {
    display: flex;
    gap: 0.4rem;
    align-items: center;
    color: var(--text-muted);
    font-size: 0.775rem;
    margin-bottom: 0.85rem;
}

.card-actions {
    margin-top: auto;
    display: flex;
    gap: 0.4rem;
}

.card-actions .btn {
    flex: 1;
    padding: 0.4rem 0.5rem;
    font-size: 0.8rem;
}

/* Application Footer */
.app-footer {
    background-color: var(--bg-surface);
    border-top: 1px solid var(--border-color);
    padding: 1.5rem;
    margin-top: auto;
}

.footer-container {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.footer-brand {
    font-weight: 700;
    font-size: 0.9rem;
    color: var(--text-primary);
}

.footer-disclaimer {
    color: var(--text-muted);
    font-size: 0.775rem;
    line-height: 1.5;
}

/* Details Dialog Modal */
.details-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background-color: var(--bg-surface);
    color: var(--text-primary);
    max-width: 580px;
    width: 90%;
    margin: auto;
    padding: 0;
    box-shadow: var(--shadow-dialog);
}

.details-dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(2px);
}

.dialog-content {
    position: relative;
    padding: 1.75rem;
}

.dialog-close {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10;
}

.dialog-close:hover {
    color: var(--text-primary);
    border-color: var(--text-muted);
}

.dialog-header-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
}

.dialog-title {
    font-size: 1.5rem;
    font-weight: 800;
    line-height: 1.25;
    margin-bottom: 0.2rem;
}

.dialog-artist {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 0.85rem;
}

.dialog-description {
    color: var(--text-secondary);
    font-size: 0.875rem;
    line-height: 1.6;
    margin-bottom: 1.1rem;
    background-color: var(--bg-elevated);
    padding: 0.85rem 1rem;
    border-radius: var(--radius-sm);
    border-left: 3px solid var(--accent-red);
}

.dialog-info-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.75rem;
    margin-bottom: 1.25rem;
}

.info-item {
    background-color: var(--bg-elevated);
    padding: 0.45rem 0.65rem;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
}

.info-label {
    font-size: 0.675rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.info-value {
    font-size: 0.825rem;
    font-weight: 600;
}

/* Video Player Modal Styling */
.video-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background-color: #121214;
    color: var(--text-primary);
    max-width: 960px;
    width: 92%;
    margin: auto;
    padding: 0;
    box-shadow: var(--shadow-dialog);
    overflow: hidden;
}

.video-dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.85);
    backdrop-filter: blur(4px);
}

.video-dialog-content {
    position: relative;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.video-modal-header {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.video-header-top {
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.video-modal-title {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--text-primary);
    letter-spacing: -0.02em;
}

.video-wrapper {
    width: 100%;
    aspect-ratio: 16/9;
    background-color: #000000;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.video-wrapper video {
    width: 100%;
    height: 100%;
    object-fit: contain;
    background-color: #000000;
    outline: none;
}

.video-modal-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 0.25rem;
}

/* Audio Player Bar */
.audio-player-bar {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background-color: var(--bg-surface);
    border-top: 1px solid var(--border-color);
    padding: 0.65rem 1.5rem;
    z-index: 90;
    transition: transform 0.2s ease;
}

.audio-player-bar.minimized {
    transform: translateY(calc(100% - 10px));
}

.player-container {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.player-toggle-btn {
    display: none; /* Mobile toggle button */
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 0.8rem;
    cursor: pointer;
}

.player-track-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    min-width: 220px;
    max-width: 300px;
}

.track-thumb {
    width: 38px;
    height: 38px;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    flex-shrink: 0;
}

.track-text {
    overflow: hidden;
}

.track-title {
    font-size: 0.85rem;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.track-artist {
    font-size: 0.75rem;
    color: var(--text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.player-controls {
    flex: 1;
    display: flex;
    justify-content: center;
}

.player-controls audio {
    width: 100%;
    max-width: 480px;
    height: 36px;
}

.player-status {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.725rem;
    color: var(--text-muted);
    min-width: 140px;
    justify-content: flex-end;
}

.event-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background-color: var(--text-muted);
}

.event-dot.active {
    background-color: var(--accent-red);
    box-shadow: 0 0 6px var(--accent-red);
}

/* Responsive Styles for Tablet and Mobile */
@media (max-width: 768px) {
    .nav-container {
        flex-wrap: wrap;
        padding: 0.65rem 1rem;
    }

    .hero-section {
        padding: 1.5rem 1.25rem;
    }

    .hero-title {
        font-size: 1.75rem;
    }

    .toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .search-box {
        min-width: 100%;
    }

    .filter-group {
        flex-direction: column;
        align-items: stretch;
    }

    .type-tabs {
        justify-content: center;
    }

    .select-wrapper select {
        width: 100%;
    }

    .video-dialog {
        width: 96%;
    }

    .video-dialog-content {
        padding: 1rem;
    }

    .video-modal-title {
        font-size: 1.2rem;
    }

    .player-toggle-btn {
        display: block;
    }

    .player-container {
        flex-direction: column;
        align-items: stretch;
        gap: 0.4rem;
    }

    .player-track-info {
        max-width: 100%;
    }

    .player-status {
        justify-content: flex-start;
    }

    body {
        padding-bottom: 140px;
    }
}

/* ==========================================================================
   StreamWave Entertainment - Responsive Media Platform Stylesheet
   Dark Graphite Theme with Restrained Red Accent
   ========================================================================== */

:root {
    --bg-base: #121214;
    --bg-surface: #18181c;
    --bg-elevated: #222228;
    --bg-hover: #2e2e36;

    --border-color: #2e2e38;
    --border-focus: #e50914;

    --text-primary: #f4f4f6;
    --text-secondary: #a0a0ab;
    --text-muted: #6e6e7a;

    --accent-red: #e50914;
    --accent-red-hover: #b80710;
    --accent-red-subtle: rgba(229, 9, 20, 0.15);

    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --radius-sm: 4px;
    --radius-md: 6px;

    --shadow-card: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-dialog: 0 16px 32px rgba(0, 0, 0, 0.7);
}

/* Base Resets */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    overflow-x: hidden;
    scroll-behavior: smooth;
}

body {
    background-color: var(--bg-base);
    color: var(--text-primary);
    font-family: var(--font-family);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    padding-bottom: 110px; /* Space so fixed audio player never obscures footer */
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
}

button, input, select {
    font-family: inherit;
    font-size: inherit;
}

/* Accessibility Focus Visible */
*:focus-visible {
    outline: 2px solid var(--accent-red);
    outline-offset: 2px;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

/* Navigation Bar */
.navbar {
    background-color: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav-container {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0.85rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-weight: 800;
    font-size: 1.2rem;
    letter-spacing: -0.02em;
    color: var(--text-primary);
}

.brand-logo-img {
    height: 48px; /* Prominent, clear logo size */
    max-height: 52px;
    width: auto;
    object-fit: contain;
    display: block;
    transition: transform 0.15s ease;
}

.brand-logo-img:hover {
    transform: scale(1.02);
}

.footer-logo-img {
    height: 36px;
    width: auto;
    object-fit: contain;
    display: block;
}

.logo-symbol {
    color: var(--accent-red);
    font-size: 1rem;
}

.logo-accent {
    color: var(--accent-red);
}

.nav-links {
    display: flex;
    gap: 1.25rem;
    align-items: center;
}

.nav-link {
    color: var(--text-secondary);
    font-size: 0.875rem;
    font-weight: 500;
    transition: color 0.15s ease;
}

.nav-link:hover, .nav-link.active {
    color: var(--text-primary);
}

.developer-link {
    color: var(--accent-red);
    font-weight: 600;
    font-size: 0.8rem;
    background-color: var(--accent-red-subtle);
    padding: 0.2rem 0.55rem;
    border-radius: var(--radius-sm);
    border: 1px solid rgba(229, 9, 20, 0.3);
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.developer-link:hover {
    background-color: rgba(229, 9, 20, 0.25);
    color: #ffffff;
}

.ext-icon {
    font-size: 0.75rem;
}

.serverless-badge-sm {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    padding: 0.2rem 0.5rem;
    border-radius: var(--radius-sm);
    font-size: 0.7rem;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.pulse-dot {
    width: 6px;
    height: 6px;
    background-color: #10b981;
    border-radius: 50%;
}

/* Main Container */
.main-content {
    max-width: 1240px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    flex: 1;
}

/* Hero / Featured Section */
.hero-section {
    position: relative;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    padding: 2.25rem 2rem;
    margin-bottom: 2rem;
    overflow: hidden;
    background-image: linear-gradient(to right, rgba(24, 24, 28, 0.95) 45%, rgba(24, 24, 28, 0.65)), url('https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 620px;
}

.hero-tag-group {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 0.4rem;
}

.hero-tag {
    color: var(--accent-red);
    font-size: 0.725rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.tech-sample-pill {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.675rem;
    font-weight: 600;
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
}

.hero-title {
    font-size: 2.25rem;
    font-weight: 800;
    line-height: 1.15;
    margin-bottom: 0.4rem;
    letter-spacing: -0.025em;
}

.hero-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-secondary);
    font-size: 0.85rem;
    margin-bottom: 0.85rem;
    flex-wrap: wrap;
}

.meta-tag {
    background-color: var(--accent-red-subtle);
    color: var(--accent-red);
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.725rem;
}

.meta-separator {
    color: var(--text-muted);
}

.hero-description {
    color: var(--text-secondary);
    font-size: 0.925rem;
    margin-bottom: 1.25rem;
    line-height: 1.55;
}

.hero-actions {
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 1.1rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.875rem;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background-color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
    background-color: var(--accent-red);
    color: #ffffff;
}

.btn-primary:hover {
    background-color: var(--accent-red-hover);
}

.btn-secondary {
    background-color: var(--bg-elevated);
    color: var(--text-primary);
    border-color: var(--border-color);
}

.btn-secondary:hover {
    background-color: var(--bg-hover);
}

/* Catalogue Section */
.section-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 1rem;
}

.section-title {
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: -0.015em;
}

.item-count {
    color: var(--text-muted);
    font-size: 0.825rem;
}

.toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 0.75rem 1rem;
    border-radius: var(--radius-md);
    align-items: center;
    justify-content: space-between;
}

.search-box {
    position: relative;
    flex: 1;
    min-width: 250px;
    display: flex;
    align-items: center;
}

.search-icon {
    position: absolute;
    left: 0.75rem;
    font-size: 0.85rem;
    color: var(--text-muted);
    pointer-events: none;
}

.search-box input {
    width: 100%;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.5rem 2.2rem 0.5rem 2.2rem;
    border-radius: var(--radius-sm);
    outline: none;
    transition: border-color 0.15s ease;
}

.search-box input:focus {
    border-color: var(--border-focus);
}

.clear-btn {
    position: absolute;
    right: 0.6rem;
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 0.95rem;
    cursor: pointer;
}

.clear-btn:hover {
    color: var(--text-primary);
}

.filter-group {
    display: flex;
    gap: 0.75rem;
    align-items: center;
    flex-wrap: wrap;
}

.type-tabs {
    display: flex;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    padding: 2px;
}

.type-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    padding: 0.35rem 0.85rem;
    border-radius: var(--radius-sm);
    font-size: 0.825rem;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease;
}

.type-tab.active {
    background-color: var(--bg-hover);
    color: var(--text-primary);
    font-weight: 600;
}

.select-wrapper select {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.4rem 0.85rem;
    border-radius: var(--radius-sm);
    outline: none;
    cursor: pointer;
    font-size: 0.825rem;
}

.select-wrapper select:focus {
    border-color: var(--border-focus);
}

/* UI States */
.state-view {
    text-align: center;
    padding: 3rem 1rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
}

.state-icon {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.state-view h3 {
    font-size: 1.05rem;
    margin-bottom: 0.3rem;
}

.state-view p {
    color: var(--text-secondary);
    font-size: 0.875rem;
    margin-bottom: 1rem;
}

.spinner {
    width: 32px;
    height: 32px;
    border: 3px solid var(--border-color);
    border-top-color: var(--accent-red);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 1rem auto;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Media Cards Grid - Responsive Breakdown */
.media-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
}

@media (max-width: 1199px) {
    .media-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 899px) {
    .media-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 599px) {
    .media-grid {
        grid-template-columns: repeat(1, 1fr);
    }
}

/* Media Card Styling */
.media-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    height: 100%;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.media-card:hover {
    transform: translateY(-2px);
    border-color: var(--text-muted);
}

.card-thumb-wrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    background-color: var(--bg-elevated);
    overflow: hidden;
    cursor: pointer;
}

.card-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.25s ease;
}

.card-thumb-wrapper:hover .card-thumb {
    transform: scale(1.04);
}

.card-badge {
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
