/**
 * StreamWave Entertainment - Frontend Application Logic
 * Academic Serverless Prototype with Movie Video Preview & Audio Player Support
 */

(function () {
    'use strict';

    // App State
    const state = {
        media: [],
        activeType: '',
        activeGenre: '',
        searchQuery: '',
        currentTrack: null,
        activeVideoMovie: null,
        lastFocusedElement: null,
        loggedVideoEvents: new Set(),
        sessionId: 'sess-' + Math.random().toString(36).substring(2, 9),
        playerMinimized: false
    };

    // DOM Elements
    const elements = {
        searchInput: document.getElementById('search-input'),
        clearSearchBtn: document.getElementById('clear-search'),
        typeTabs: document.querySelectorAll('.type-tab'),
        genreSelect: document.getElementById('genre-select'),
        itemCount: document.getElementById('item-count'),

        // Views
        loadingState: document.getElementById('loading-state'),
        errorState: document.getElementById('error-state'),
        errorMessage: document.getElementById('error-message'),
        emptyState: document.getElementById('empty-state'),
        mediaGrid: document.getElementById('media-grid'),

        // Details Modal
        detailsDialog: document.getElementById('details-dialog'),
        closeDialogBtn: document.getElementById('close-dialog'),
        dialogBody: document.getElementById('dialog-body'),

        // Video Modal
        videoDialog: document.getElementById('video-dialog'),
        closeVideoBtn: document.getElementById('close-video-btn'),
        closeVideoX: document.getElementById('close-video-x'),
        videoModalTitle: document.getElementById('video-modal-title'),
        videoElement: document.getElementById('html5-video'),
        videoSource: document.getElementById('video-source'),
        videoReplayBtn: document.getElementById('video-replay-btn'),

        // Audio Player
        audioBar: document.getElementById('audio-player-bar'),
        playerToggleBtn: document.getElementById('player-toggle-btn'),
        audioElement: document.getElementById('html5-audio'),
        audioSource: document.getElementById('audio-source'),
        playerThumb: document.getElementById('player-thumb'),
        playerTitle: document.getElementById('player-title'),
        playerArtist: document.getElementById('player-artist'),
        eventLogText: document.getElementById('event-log-text'),
        eventDot: document.querySelector('.event-dot')
    };

    /**
     * Initializes event listeners and fetches initial media list
     */
    function init() {
        bindEvents();
        fetchMedia();
    }

    /**
     * Binds user interaction listeners
     */
    function bindEvents() {
        // Search input with debounce
        let searchTimeout;
        elements.searchInput.addEventListener('input', (e) => {
            state.searchQuery = e.target.value.trim();
            elements.clearSearchBtn.style.display = state.searchQuery ? 'block' : 'none';
            clearTimeout(searchTimeout);
            searchTimeout = setTimeout(() => fetchMedia(), 250);
        });

        elements.clearSearchBtn.addEventListener('click', () => {
            elements.searchInput.value = '';
            state.searchQuery = '';
            elements.clearSearchBtn.style.display = 'none';
            fetchMedia();
        });

        // Type tabs
        elements.typeTabs.forEach((tab) => {
            tab.addEventListener('click', () => {
                elements.typeTabs.forEach((t) => {
                    t.classList.remove('active');
                    t.setAttribute('aria-selected', 'false');
                });
                tab.classList.add('active');
                tab.setAttribute('aria-selected', 'true');
                state.activeType = tab.getAttribute('data-type');
                fetchMedia();
            });
        });

        // Genre filter select
        elements.genreSelect.addEventListener('change', (e) => {
            state.activeGenre = e.target.value;
            fetchMedia();
        });

        // Details Modal close button
        elements.closeDialogBtn.addEventListener('click', () => {
            elements.detailsDialog.close();
        });

        // Close details modal on backdrop click
        elements.detailsDialog.addEventListener('click', (e) => {
            const rect = elements.detailsDialog.getBoundingClientRect();
            const isInDialog = (
                rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                rect.left <= e.clientX && e.clientX <= rect.left + rect.width
            );
            if (!isInDialog) {
                elements.detailsDialog.close();
            }
        });

        // Video Modal Close Handlers
        if (elements.closeVideoBtn) {
            elements.closeVideoBtn.addEventListener('click', closeVideoModal);
        }
        if (elements.closeVideoX) {
            elements.closeVideoX.addEventListener('click', closeVideoModal);
        }

        // Close video modal on backdrop click
        if (elements.videoDialog) {
            elements.videoDialog.addEventListener('click', (e) => {
                const rect = elements.videoDialog.getBoundingClientRect();
                const isInDialog = (
                    rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                    rect.left <= e.clientX && e.clientX <= rect.left + rect.width
                );
                if (!isInDialog) {
                    closeVideoModal();
                }
            });
        }

        // Video ended listener -> show Replay button
        if (elements.videoElement) {
            elements.videoElement.addEventListener('ended', () => {
                if (elements.videoReplayBtn) {
                    elements.videoReplayBtn.style.display = 'inline-flex';
                }
            });

            // Video play listener -> trigger POST /api/play-events (once per movie playback start)
            elements.videoElement.addEventListener('play', () => {
                if (state.activeVideoMovie) {
                    const movieId = state.activeVideoMovie.id;
                    if (!state.loggedVideoEvents.has(movieId)) {
                        state.loggedVideoEvents.add(movieId);
                        logPlayEvent(movieId);
                    }
                }
            });
        }

        // Replay button click handler
        if (elements.videoReplayBtn) {
            elements.videoReplayBtn.addEventListener('click', () => {
                elements.videoReplayBtn.style.display = 'none';
                if (elements.videoElement) {
                    elements.videoElement.currentTime = 0;
                    elements.videoElement.play().catch(err => console.warn('Replay play error:', err));
                }
            });
        }

        // Global Escape key listener for dialog accessibility
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                if (elements.videoDialog && elements.videoDialog.open) {
                    closeVideoModal();
                } else if (elements.detailsDialog && elements.detailsDialog.open) {
                    elements.detailsDialog.close();
                }
            }
        });

        // Player mobile minimize toggle
        if (elements.playerToggleBtn) {
            elements.playerToggleBtn.addEventListener('click', () => {
                state.playerMinimized = !state.playerMinimized;
                elements.audioBar.classList.toggle('minimized', state.playerMinimized);
                elements.playerToggleBtn.textContent = state.playerMinimized ? '▲' : '▼';
                elements.playerToggleBtn.setAttribute('aria-label', state.playerMinimized ? 'Expand audio player' : 'Minimize audio player');
            });
        }

        // Audio element playback listener to trigger POST /api/play-events for music
        elements.audioElement.addEventListener('play', () => {
            if (state.currentTrack) {
                logPlayEvent(state.currentTrack.id);
            }
        });
    }

    /**
     * Fetches media items from FastAPI backend /api/media endpoint
     */
    async function fetchMedia() {
        showView('loading');

        try {
            const params = new URLSearchParams();
            if (state.searchQuery) params.append('query', state.searchQuery);
            if (state.activeType) params.append('type', state.activeType);
            if (state.activeGenre) params.append('genre', state.activeGenre);

            const url = `/api/media${params.toString() ? '?' + params.toString() : ''}`;
            const response = await fetch(url);

            if (!response.ok) {
                throw new Error(`Server returned HTTP ${response.status}`);
            }

            state.media = await response.json();
            renderMediaGrid();
        } catch (err) {
            console.error('Error fetching media:', err);
            elements.errorMessage.textContent = err.message || 'Failed to connect to StreamWave API.';
            showView('error');
        }
    }

    /**
     * Renders media items in card grid with concise playback labels ("Watch" / "Play")
     */
    function renderMediaGrid() {
        elements.itemCount.textContent = `${state.media.length} item${state.media.length === 1 ? '' : 's'}`;

        if (state.media.length === 0) {
            showView('empty');
            return;
        }

        elements.mediaGrid.innerHTML = state.media.map((item) => {
            const isMovie = item.type === 'movie';
            const playLabel = isMovie ? 'Watch' : 'Play';
            const playIcon = isMovie ? '🎬' : '🎵';
            const clickHandler = isMovie
                ? `window.streamWaveApp.playMoviePreview('${item.id}', this)`
                : `window.streamWaveApp.playMedia('${item.id}')`;
            const escapedTitle = escapeHtml(item.title);

            return `
                <article class="media-card" data-id="${item.id}">
                    <div class="card-thumb-wrapper" onclick="window.streamWaveApp.openDetails('${item.id}', this)" title="View details for ${escapedTitle}">
                        <img class="card-thumb" src="${item.cover_image || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=600&q=80'}" alt="${escapedTitle}" loading="lazy">
                        <span class="card-badge">${escapeHtml(item.type)}</span>
                        <span class="tech-sample-tag">5-sec technical preview</span>
                    </div>
                    <div class="card-content">
                        <h3 class="card-title" title="${escapedTitle}" onclick="window.streamWaveApp.openDetails('${item.id}', this)">${escapedTitle}</h3>
                        <div class="card-subtitle">${escapeHtml(item.artist_or_director)}</div>
                        <div class="card-meta">
                            <span>${item.year}</span>
                            <span>•</span>
                            <span>${escapeHtml(item.genre)}</span>
                            <span>•</span>
                            <span>${escapeHtml(item.duration)}</span>
                        </div>
                        <div class="card-actions">
                            <button class="btn btn-primary" onclick="${clickHandler}" aria-label="${playLabel} ${escapedTitle}">
                                ${playIcon} ${playLabel}
                            </button>
                            <button class="btn btn-secondary" onclick="window.streamWaveApp.openDetails('${item.id}', this)" aria-label="View details for ${escapedTitle}">
                                ℹ Details
                            </button>
                        </div>
                    </div>
                </article>
            `;
        }).join('');

        showView('grid');
    }

    /**
     * Switch view state (loading, error, empty, grid)
     */
    function showView(viewName) {
        elements.loadingState.style.display = viewName === 'loading' ? 'block' : 'none';
        elements.errorState.style.display = viewName === 'error' ? 'block' : 'none';
        elements.emptyState.style.display = viewName === 'empty' ? 'block' : 'none';
        elements.mediaGrid.style.display = viewName === 'grid' ? 'grid' : 'none';
    }

    /**
     * Opens professional video player modal for movie previews
     */
    async function playMoviePreview(id, triggerElement) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.activeVideoMovie = item;
        state.lastFocusedElement = triggerElement || document.activeElement;

        // Populate title
        elements.videoModalTitle.textContent = item.title;

        // Set video source to static preview MP4 URL
        const videoUrl = item.preview_url || item.media_url || '/media/streamwave-preview.mp4';
        elements.videoSource.src = videoUrl;
        elements.videoElement.load();

        // Reset replay button
        if (elements.videoReplayBtn) {
            elements.videoReplayBtn.style.display = 'none';
        }

        // Lock scroll & show modal
        document.body.style.overflow = 'hidden';
        elements.videoDialog.showModal();

        // Start playback after user click interaction
        try {
            await elements.videoElement.play();
        } catch (e) {
            console.warn('Video play prevented or interrupted:', e);
        }

        // Log playback event
        if (!state.loggedVideoEvents.has(id)) {
            state.loggedVideoEvents.add(id);
            logPlayEvent(id);
        }
    }

    /**
     * Closes video modal, resets playback position, and restores focus/scrolling
     */
    function closeVideoModal() {
        if (elements.videoElement) {
            elements.videoElement.pause();
            elements.videoElement.currentTime = 0;
        }

        state.activeVideoMovie = null;
        document.body.style.overflow = '';

        if (elements.videoDialog && elements.videoDialog.open) {
            elements.videoDialog.close();
        }

        // Restore keyboard focus to triggering element
        if (state.lastFocusedElement && typeof state.lastFocusedElement.focus === 'function') {
            state.lastFocusedElement.focus();
        }
    }

    /**
     * Plays music item audio file using HTML5 Audio Player
     */
    async function playMedia(id) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        // If item is a movie, delegate to playMoviePreview
        if (item.type === 'movie') {
            playMoviePreview(id);
            return;
        }

        state.currentTrack = item;
        elements.playerTitle.textContent = item.title;
        elements.playerArtist.textContent = `${item.artist_or_director} (${item.genre})`;
        elements.playerThumb.textContent = '🎵';

        // Unminimize player bar if minimized
        if (state.playerMinimized) {
            state.playerMinimized = false;
            elements.audioBar.classList.remove('minimized');
            if (elements.playerToggleBtn) elements.playerToggleBtn.textContent = '▼';
        }

        // Set audio source to static file URL (defaults to /media/demo.wav for demo)
        const audioUrl = item.media_url || '/media/demo.wav';
        elements.audioSource.src = audioUrl;
        elements.audioElement.load();

        try {
            await elements.audioElement.play();
        } catch (e) {
            console.warn('Autoplay prevented or failed:', e);
        }

        // Trigger POST /api/play-events
        logPlayEvent(id);
    }

    /**
     * Fetches a single media item by ID
     */
    async function fetchSingleItem(id) {
        try {
            const res = await fetch(`/api/media/${id}`);
            if (res.ok) return await res.json();
        } catch (e) {
            console.error('Error fetching item detail:', e);
        }
        return null;
    }

    /**
     * Sends playback event log to POST /api/play-events
     */
    async function logPlayEvent(mediaId) {
        updateEventBadge('Logging...', true);
        try {
            const payload = {
                media_id: mediaId,
                session_id: state.sessionId,
                client_timestamp: new Date().toISOString()
            };

            const res = await fetch('/api/play-events', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                const data = await res.json();
                updateEventBadge(`Event Logged (${data.event.server_timestamp.slice(11, 19)} UTC)`, false);
            } else {
                updateEventBadge('Event Log Error', false);
            }
        } catch (err) {
            console.error('Play event error:', err);
            updateEventBadge('Event Log Failed', false);
        }
    }

    /**
     * Updates status dot badge near audio player
     */
    function updateEventBadge(text, isActive) {
        elements.eventLogText.textContent = text;
        if (isActive) {
            elements.eventDot.classList.add('active');
        } else {
            elements.eventDot.classList.remove('active');
        }
    }

    /**
     * Opens accessible details dialog
     */
    async function openDetails(id, triggerElement) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.lastFocusedElement = triggerElement || document.activeElement;
        const isMovie = item.type === 'movie';
        const playLabel = isMovie ? 'Watch' : 'Play';
        const playIcon = isMovie ? '🎬' : '🎵';
        const clickHandler = isMovie
            ? `window.streamWaveApp.playMoviePreview('${item.id}'); document.getElementById('details-dialog').close();`
            : `window.streamWaveApp.playMedia('${item.id}'); document.getElementById('details-dialog').close();`;

        elements.dialogBody.innerHTML = `
            <div class="dialog-header-meta">
                <span class="meta-tag">${escapeHtml(item.type)}</span>
                <span class="meta-separator">•</span>
                <span style="color: var(--text-secondary); font-size: 0.85rem;">${item.year}</span>
                <span class="meta-separator">•</span>
                <span class="tech-sample-pill">${isMovie ? '5-sec MP4 preview' : 'Technical audio sample'}</span>
            </div>
            <h2 id="dialog-title" class="dialog-title">${escapeHtml(item.title)}</h2>
            <div class="dialog-artist">By ${escapeHtml(item.artist_or_director)}</div>
            <p id="dialog-desc" class="dialog-description">${escapeHtml(item.description)}</p>

            <div class="dialog-info-grid">
                <div class="info-item">
                    <div class="info-label">Genre</div>
                    <div class="info-value">${escapeHtml(item.genre)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Duration</div>
                    <div class="info-value">${escapeHtml(item.duration)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Media ID</div>
                    <div class="info-value">${escapeHtml(item.id)}</div>
                </div>
            </div>

            <div class="dialog-actions" style="display: flex; gap: 0.75rem;">
                <button class="btn btn-primary" onclick="${clickHandler}">
                    ${playIcon} ${playLabel}
                </button>
            </div>
        `;

        elements.detailsDialog.showModal();
    }

    /**
     * Resets filter parameters
     */
    function resetFilters() {
        state.searchQuery = '';
        state.activeType = '';
        state.activeGenre = '';
        elements.searchInput.value = '';
        elements.genreSelect.value = '';
        elements.clearSearchBtn.style.display = 'none';
        elements.typeTabs.forEach((tab, index) => {
            tab.classList.toggle('active', index === 0);
            tab.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
        });
        fetchMedia();
    }

    /**
     * Basic HTML escaping to prevent XSS
     */
    function escapeHtml(str) {
        if (!str) return '';
        return str
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    // Expose global methods for inline button onclick handlers
    window.streamWaveApp = {
        fetchMedia,
        playMedia,
        playMoviePreview,
        openDetails,
        closeVideoModal,
        resetFilters
    };

    // Initialize on DOM load
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/**
 * StreamWave Entertainment - Frontend Application Logic
 * Academic Serverless Prototype with Movie Video Preview & Audio Player Support
 */

(function () {
    'use strict';

    // App State
    const state = {
        media: [],
        activeType: '',
        activeGenre: '',
        searchQuery: '',
        currentTrack: null,
        activeVideoMovie: null,
        lastFocusedElement: null,
        loggedVideoEvents: new Set(),
        sessionId: 'sess-' + Math.random().toString(36).substring(2, 9),
        playerMinimized: false
    };

    // DOM Elements
    const elements = {
        searchInput: document.getElementById('search-input'),
        clearSearchBtn: document.getElementById('clear-search'),
        typeTabs: document.querySelectorAll('.type-tab'),
        genreSelect: document.getElementById('genre-select'),
        itemCount: document.getElementById('item-count'),

        // Views
        loadingState: document.getElementById('loading-state'),
        errorState: document.getElementById('error-state'),
        errorMessage: document.getElementById('error-message'),
        emptyState: document.getElementById('empty-state'),
        mediaGrid: document.getElementById('media-grid'),

        // Details Modal
        detailsDialog: document.getElementById('details-dialog'),
        closeDialogBtn: document.getElementById('close-dialog'),
        dialogBody: document.getElementById('dialog-body'),

        // Video Modal
        videoDialog: document.getElementById('video-dialog'),
        closeVideoBtn: document.getElementById('close-video-btn'),
        closeVideoX: document.getElementById('close-video-x'),
        videoModalTitle: document.getElementById('video-modal-title'),
        videoElement: document.getElementById('html5-video'),
        videoSource: document.getElementById('video-source'),
        videoReplayBtn: document.getElementById('video-replay-btn'),

        // Audio Player
        audioBar: document.getElementById('audio-player-bar'),
        playerToggleBtn: document.getElementById('player-toggle-btn'),
        audioElement: document.getElementById('html5-audio'),
        audioSource: document.getElementById('audio-source'),
        playerThumb: document.getElementById('player-thumb'),
        playerTitle: document.getElementById('player-title'),
        playerArtist: document.getElementById('player-artist'),
        eventLogText: document.getElementById('event-log-text'),
        eventDot: document.querySelector('.event-dot')
    };

    /**
     * Initializes event listeners and fetches initial media list
     */
    function init() {
        bindEvents();
        fetchMedia();
    }

    /**
     * Binds user interaction listeners
     */
    function bindEvents() {
        // Search input with debounce
        let searchTimeout;
        elements.searchInput.addEventListener('input', (e) => {
            state.searchQuery = e.target.value.trim();
            elements.clearSearchBtn.style.display = state.searchQuery ? 'block' : 'none';
            clearTimeout(searchTimeout);
            searchTimeout = setTimeout(() => fetchMedia(), 250);
        });

        elements.clearSearchBtn.addEventListener('click', () => {
            elements.searchInput.value = '';
            state.searchQuery = '';
            elements.clearSearchBtn.style.display = 'none';
            fetchMedia();
        });

        // Type tabs
        elements.typeTabs.forEach((tab) => {
            tab.addEventListener('click', () => {
                elements.typeTabs.forEach((t) => {
                    t.classList.remove('active');
                    t.setAttribute('aria-selected', 'false');
                });
                tab.classList.add('active');
                tab.setAttribute('aria-selected', 'true');
                state.activeType = tab.getAttribute('data-type');
                fetchMedia();
            });
        });

        // Genre filter select
        elements.genreSelect.addEventListener('change', (e) => {
            state.activeGenre = e.target.value;
            fetchMedia();
        });

        // Details Modal close button
        elements.closeDialogBtn.addEventListener('click', () => {
            elements.detailsDialog.close();
        });

        // Close details modal on backdrop click
        elements.detailsDialog.addEventListener('click', (e) => {
            const rect = elements.detailsDialog.getBoundingClientRect();
            const isInDialog = (
                rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                rect.left <= e.clientX && e.clientX <= rect.left + rect.width
            );
            if (!isInDialog) {
                elements.detailsDialog.close();
            }
        });

        // Video Modal Close Handlers
        if (elements.closeVideoBtn) {
            elements.closeVideoBtn.addEventListener('click', closeVideoModal);
        }
        if (elements.closeVideoX) {
            elements.closeVideoX.addEventListener('click', closeVideoModal);
        }

        // Close video modal on backdrop click
        if (elements.videoDialog) {
            elements.videoDialog.addEventListener('click', (e) => {
                const rect = elements.videoDialog.getBoundingClientRect();
                const isInDialog = (
                    rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                    rect.left <= e.clientX && e.clientX <= rect.left + rect.width
                );
                if (!isInDialog) {
                    closeVideoModal();
                }
            });
        }

        // Video ended listener -> show Replay button
        if (elements.videoElement) {
            elements.videoElement.addEventListener('ended', () => {
                if (elements.videoReplayBtn) {
                    elements.videoReplayBtn.style.display = 'inline-flex';
                }
            });

            // Video play listener -> trigger POST /api/play-events (once per movie playback start)
            elements.videoElement.addEventListener('play', () => {
                if (state.activeVideoMovie) {
                    const movieId = state.activeVideoMovie.id;
                    if (!state.loggedVideoEvents.has(movieId)) {
                        state.loggedVideoEvents.add(movieId);
                        logPlayEvent(movieId);
                    }
                }
            });
        }

        // Replay button click handler
        if (elements.videoReplayBtn) {
            elements.videoReplayBtn.addEventListener('click', () => {
                elements.videoReplayBtn.style.display = 'none';
                if (elements.videoElement) {
                    elements.videoElement.currentTime = 0;
                    elements.videoElement.play().catch(err => console.warn('Replay play error:', err));
                }
            });
        }

        // Global Escape key listener for dialog accessibility
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                if (elements.videoDialog && elements.videoDialog.open) {
                    closeVideoModal();
                } else if (elements.detailsDialog && elements.detailsDialog.open) {
                    elements.detailsDialog.close();
                }
            }
        });

        // Player mobile minimize toggle
        if (elements.playerToggleBtn) {
            elements.playerToggleBtn.addEventListener('click', () => {
                state.playerMinimized = !state.playerMinimized;
                elements.audioBar.classList.toggle('minimized', state.playerMinimized);
                elements.playerToggleBtn.textContent = state.playerMinimized ? '▲' : '▼';
                elements.playerToggleBtn.setAttribute('aria-label', state.playerMinimized ? 'Expand audio player' : 'Minimize audio player');
            });
        }

        // Audio element playback listener to trigger POST /api/play-events for music
        elements.audioElement.addEventListener('play', () => {
            if (state.currentTrack) {
                logPlayEvent(state.currentTrack.id);
            }
        });
    }

    /**
     * Fetches media items from FastAPI backend /api/media endpoint
     */
    async function fetchMedia() {
        showView('loading');

        try {
            const params = new URLSearchParams();
            if (state.searchQuery) params.append('query', state.searchQuery);
            if (state.activeType) params.append('type', state.activeType);
            if (state.activeGenre) params.append('genre', state.activeGenre);

            const url = `/api/media${params.toString() ? '?' + params.toString() : ''}`;
            const response = await fetch(url);

            if (!response.ok) {
                throw new Error(`Server returned HTTP ${response.status}`);
            }

            state.media = await response.json();
            renderMediaGrid();
        } catch (err) {
            console.error('Error fetching media:', err);
            elements.errorMessage.textContent = err.message || 'Failed to connect to StreamWave API.';
            showView('error');
        }
    }

    /**
     * Renders media items in card grid with StreamWave play symbol ("▶ Watch" / "▶ Play")
     */
    function renderMediaGrid() {
        elements.itemCount.textContent = `${state.media.length} item${state.media.length === 1 ? '' : 's'}`;

        if (state.media.length === 0) {
            showView('empty');
            return;
        }

        elements.mediaGrid.innerHTML = state.media.map((item) => {
            const isMovie = item.type === 'movie';
            const playLabel = isMovie ? 'Watch' : 'Play';
            const playIcon = '▶';
            const clickHandler = isMovie
                ? `window.streamWaveApp.playMoviePreview('${item.id}', this)`
                : `window.streamWaveApp.playMedia('${item.id}')`;
            const escapedTitle = escapeHtml(item.title);

            return `
                <article class="media-card" data-id="${item.id}">
                    <div class="card-thumb-wrapper" onclick="window.streamWaveApp.openDetails('${item.id}', this)" title="View details for ${escapedTitle}">
                        <img class="card-thumb" src="${item.cover_image || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=600&q=80'}" alt="${escapedTitle}" loading="lazy">
                        <span class="card-badge">${escapeHtml(item.type)}</span>
                        <span class="tech-sample-tag">5-sec technical preview</span>
                    </div>
                    <div class="card-content">
                        <h3 class="card-title" title="${escapedTitle}" onclick="window.streamWaveApp.openDetails('${item.id}', this)">${escapedTitle}</h3>
                        <div class="card-subtitle">${escapeHtml(item.artist_or_director)}</div>
                        <div class="card-meta">
                            <span>${item.year}</span>
                            <span>•</span>
                            <span>${escapeHtml(item.genre)}</span>
                            <span>•</span>
                            <span>${escapeHtml(item.duration)}</span>
                        </div>
                        <div class="card-actions">
                            <button class="btn btn-primary" onclick="${clickHandler}" aria-label="${playLabel} ${escapedTitle}">
                                ${playIcon} ${playLabel}
                            </button>
                            <button class="btn btn-secondary" onclick="window.streamWaveApp.openDetails('${item.id}', this)" aria-label="View details for ${escapedTitle}">
                                ℹ Details
                            </button>
                        </div>
                    </div>
                </article>
            `;
        }).join('');

        showView('grid');
    }

    /**
     * Switch view state (loading, error, empty, grid)
     */
    function showView(viewName) {
        elements.loadingState.style.display = viewName === 'loading' ? 'block' : 'none';
        elements.errorState.style.display = viewName === 'error' ? 'block' : 'none';
        elements.emptyState.style.display = viewName === 'empty' ? 'block' : 'none';
        elements.mediaGrid.style.display = viewName === 'grid' ? 'grid' : 'none';
    }

    /**
     * Opens professional video player modal for movie previews
     */
    async function playMoviePreview(id, triggerElement) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.activeVideoMovie = item;
        state.lastFocusedElement = triggerElement || document.activeElement;

        // Populate title
        elements.videoModalTitle.textContent = item.title;

        // Set video source to static preview MP4 URL
        const videoUrl = item.preview_url || item.media_url || '/media/streamwave-preview.mp4';
        elements.videoSource.src = videoUrl;
        elements.videoElement.load();

        // Reset replay button
        if (elements.videoReplayBtn) {
            elements.videoReplayBtn.style.display = 'none';
        }

        // Lock scroll & show modal
        document.body.style.overflow = 'hidden';
        elements.videoDialog.showModal();

        // Start playback after user click interaction
        try {
            await elements.videoElement.play();
        } catch (e) {
            console.warn('Video play prevented or interrupted:', e);
        }

        // Log playback event
        if (!state.loggedVideoEvents.has(id)) {
            state.loggedVideoEvents.add(id);
            logPlayEvent(id);
        }
    }

    /**
     * Closes video modal, resets playback position, and restores focus/scrolling
     */
    function closeVideoModal() {
        if (elements.videoElement) {
            elements.videoElement.pause();
            elements.videoElement.currentTime = 0;
        }

        state.activeVideoMovie = null;
        document.body.style.overflow = '';

        if (elements.videoDialog && elements.videoDialog.open) {
            elements.videoDialog.close();
        }

        // Restore keyboard focus to triggering element
        if (state.lastFocusedElement && typeof state.lastFocusedElement.focus === 'function') {
            state.lastFocusedElement.focus();
        }
    }

    /**
     * Plays music item audio file using HTML5 Audio Player
     */
    async function playMedia(id) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        // If item is a movie, delegate to playMoviePreview
        if (item.type === 'movie') {
            playMoviePreview(id);
            return;
        }

        state.currentTrack = item;
        elements.playerTitle.textContent = item.title;
        elements.playerArtist.textContent = `${item.artist_or_director} (${item.genre})`;
        elements.playerThumb.textContent = '🎵';

        // Unminimize player bar if minimized
        if (state.playerMinimized) {
            state.playerMinimized = false;
            elements.audioBar.classList.remove('minimized');
            if (elements.playerToggleBtn) elements.playerToggleBtn.textContent = '▼';
        }

        // Set audio source to static file URL (defaults to /media/demo.wav for demo)
        const audioUrl = item.media_url || '/media/demo.wav';
        elements.audioSource.src = audioUrl;
        elements.audioElement.load();

        try {
            await elements.audioElement.play();
        } catch (e) {
            console.warn('Autoplay prevented or failed:', e);
        }

        // Trigger POST /api/play-events
        logPlayEvent(id);
    }

    /**
     * Fetches a single media item by ID
     */
    async function fetchSingleItem(id) {
        try {
            const res = await fetch(`/api/media/${id}`);
            if (res.ok) return await res.json();
        } catch (e) {
            console.error('Error fetching item detail:', e);
        }
        return null;
    }

    /**
     * Sends playback event log to POST /api/play-events
     */
    async function logPlayEvent(mediaId) {
        updateEventBadge('Logging...', true);
        try {
            const payload = {
                media_id: mediaId,
                session_id: state.sessionId,
                client_timestamp: new Date().toISOString()
            };

            const res = await fetch('/api/play-events', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                const data = await res.json();
                updateEventBadge(`Event Logged (${data.event.server_timestamp.slice(11, 19)} UTC)`, false);
            } else {
                updateEventBadge('Event Log Error', false);
            }
        } catch (err) {
            console.error('Play event error:', err);
            updateEventBadge('Event Log Failed', false);
        }
    }

    /**
     * Updates status dot badge near audio player
     */
    function updateEventBadge(text, isActive) {
        elements.eventLogText.textContent = text;
        if (isActive) {
            elements.eventDot.classList.add('active');
        } else {
            elements.eventDot.classList.remove('active');
        }
    }

    /**
     * Opens accessible details dialog
     */
    async function openDetails(id, triggerElement) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.lastFocusedElement = triggerElement || document.activeElement;
        const isMovie = item.type === 'movie';
        const playLabel = isMovie ? 'Watch' : 'Play';
        const playIcon = '▶';
        const clickHandler = isMovie
            ? `window.streamWaveApp.playMoviePreview('${item.id}'); document.getElementById('details-dialog').close();`
            : `window.streamWaveApp.playMedia('${item.id}'); document.getElementById('details-dialog').close();`;

        elements.dialogBody.innerHTML = `
            <div class="dialog-header-meta">
                <span class="meta-tag">${escapeHtml(item.type)}</span>
                <span class="meta-separator">•</span>
                <span style="color: var(--text-secondary); font-size: 0.85rem;">${item.year}</span>
                <span class="meta-separator">•</span>
                <span class="tech-sample-pill">${isMovie ? '5-sec MP4 preview' : 'Technical audio sample'}</span>
            </div>
            <h2 id="dialog-title" class="dialog-title">${escapeHtml(item.title)}</h2>
            <div class="dialog-artist">By ${escapeHtml(item.artist_or_director)}</div>
            <p id="dialog-desc" class="dialog-description">${escapeHtml(item.description)}</p>

            <div class="dialog-info-grid">
                <div class="info-item">
                    <div class="info-label">Genre</div>
                    <div class="info-value">${escapeHtml(item.genre)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Duration</div>
                    <div class="info-value">${escapeHtml(item.duration)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Media ID</div>
                    <div class="info-value">${escapeHtml(item.id)}</div>
                </div>
            </div>

            <div class="dialog-actions" style="display: flex; gap: 0.75rem;">
                <button class="btn btn-primary" onclick="${clickHandler}">
                    ${playIcon} ${playLabel}
                </button>
            </div>
        `;

        elements.detailsDialog.showModal();
    }

    /**
     * Resets filter parameters
     */
    function resetFilters() {
        state.searchQuery = '';
        state.activeType = '';
        state.activeGenre = '';
        elements.searchInput.value = '';
        elements.genreSelect.value = '';
        elements.clearSearchBtn.style.display = 'none';
        elements.typeTabs.forEach((tab, index) => {
            tab.classList.toggle('active', index === 0);
            tab.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
        });
        fetchMedia();
    }

    /**
     * Basic HTML escaping to prevent XSS
     */
    function escapeHtml(str) {
        if (!str) return '';
        return str
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    // Expose global methods for inline button onclick handlers
    window.streamWaveApp = {
        fetchMedia,
        playMedia,
        playMoviePreview,
        openDetails,
        closeVideoModal,
        resetFilters
    };

    // Initialize on DOM load
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/* ==========================================================================
   StreamWave Entertainment - Responsive Media Platform Stylesheet
   Dark Graphite Theme with Restrained Red Accent
   ========================================================================== */

:root {
    --bg-base: #121214;
    --bg-surface: #18181c;
    --bg-elevated: #222228;
    --bg-hover: #2e2e36;

    --border-color: #2e2e38;
    --border-focus: #e50914;

    --text-primary: #f4f4f6;
    --text-secondary: #a0a0ab;
    --text-muted: #6e6e7a;

    --accent-red: #e50914;
    --accent-red-hover: #b80710;
    --accent-red-subtle: rgba(229, 9, 20, 0.15);

    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --radius-sm: 4px;
    --radius-md: 6px;

    --shadow-card: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-dialog: 0 16px 32px rgba(0, 0, 0, 0.7);
}

/* Base Resets */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    overflow-x: hidden;
    scroll-behavior: smooth;
}

body {
    background-color: var(--bg-base);
    color: var(--text-primary);
    font-family: var(--font-family);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    padding-bottom: 110px; /* Space so fixed audio player never obscures footer */
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
}

button, input, select {
    font-family: inherit;
    font-size: inherit;
}

/* Accessibility Focus Visible */
*:focus-visible {
    outline: 2px solid var(--accent-red);
    outline-offset: 2px;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}

/* Navigation Bar */
.navbar {
    background-color: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav-container {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0.85rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-weight: 800;
    font-size: 1.2rem;
    letter-spacing: -0.02em;
    color: var(--text-primary);
}

.brand-logo-img {
    height: 48px;
    max-height: 52px;
    width: auto;
    object-fit: contain;
    display: block;
    transition: transform 0.15s ease;
}

.brand-logo-img:hover {
    transform: scale(1.02);
}

.footer-logo-img {
    height: 36px;
    width: auto;
    object-fit: contain;
    display: block;
}

.logo-symbol {
    color: var(--accent-red);
    font-size: 1rem;
}

.logo-accent {
    color: var(--accent-red);
}

.nav-links {
    display: flex;
    gap: 1.25rem;
    align-items: center;
}

.nav-link {
    color: var(--text-secondary);
    font-size: 0.875rem;
    font-weight: 500;
    transition: color 0.15s ease;
}

.nav-link:hover, .nav-link.active {
    color: var(--text-primary);
}

.developer-link {
    color: var(--accent-red);
    font-weight: 600;
    font-size: 0.8rem;
    background-color: var(--accent-red-subtle);
    padding: 0.2rem 0.55rem;
    border-radius: var(--radius-sm);
    border: 1px solid rgba(229, 9, 20, 0.3);
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.developer-link:hover {
    background-color: rgba(229, 9, 20, 0.25);
    color: #ffffff;
}

.btn-signin-nav {
    font-size: 0.85rem;
    padding: 0.35rem 0.95rem;
}

.ext-icon {
    font-size: 0.75rem;
}

/* Main Container */
.main-content {
    max-width: 1240px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    flex: 1;
}

/* Netflix-Style Landing Hero Section */
.landing-hero {
    position: relative;
    padding: 5rem 1.5rem 5.5rem 1.5rem;
    margin-bottom: 2.5rem;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-color);
    background-color: #0b0b0d;
    background-image: radial-gradient(circle at center, rgba(229, 9, 20, 0.18) 0%, rgba(18, 18, 20, 0.96) 75%), url('https://images.unsplash.com/photo-1574375927938-d5a98e8ffe85?auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
    text-align: center;
    overflow: hidden;
    box-shadow: inset 0 0 120px rgba(0, 0, 0, 0.9);
}

.landing-backdrop {
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, rgba(18, 18, 20, 0.82) 0%, rgba(18, 18, 20, 0.65) 50%, rgba(18, 18, 20, 0.98) 100%);
    pointer-events: none;
}

.landing-content {
    position: relative;
    z-index: 2;
    max-width: 820px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.15rem;
}

.serverless-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    background-color: rgba(24, 24, 28, 0.92);
    border: 1px solid var(--border-color);
    padding: 0.25rem 0.75rem;
    border-radius: 50px;
    font-size: 0.725rem;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.landing-title {
    font-size: 3rem;
    font-weight: 900;
    line-height: 1.12;
    letter-spacing: -0.03em;
    color: #ffffff;
}

.landing-subtitle {
    font-size: 1.35rem;
    font-weight: 500;
    color: var(--text-primary);
}

.landing-prompt {
    font-size: 1.05rem;
    color: var(--text-secondary);
    margin-top: 0.15rem;
}

.landing-email-form {
    display: flex;
    width: 100%;
    max-width: 620px;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.landing-email-form input {
    flex: 1;
    background-color: rgba(22, 22, 26, 0.9);
    border: 1px solid rgba(255, 255, 255, 0.35);
    color: #ffffff;
    padding: 0.9rem 1.25rem;
    border-radius: var(--radius-sm);
    font-size: 1rem;
    outline: none;
    transition: border-color 0.15s ease;
}

.landing-email-form input:focus {
    border-color: var(--accent-red);
}

.btn-get-started {
    font-size: 1.25rem;
    font-weight: 700;
    padding: 0.9rem 1.75rem;
    white-space: nowrap;
    border-radius: var(--radius-sm);
}

.btn-get-started .chevron {
    font-size: 1.4rem;
    font-weight: 400;
    margin-left: 0.25rem;
}

/* Hero / Featured Section */
.hero-section {
    position: relative;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    padding: 2.25rem 2rem;
    margin-bottom: 2rem;
    overflow: hidden;
    background-image: linear-gradient(to right, rgba(24, 24, 28, 0.95) 45%, rgba(24, 24, 28, 0.65)), url('https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 620px;
}

.hero-tag-group {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 0.4rem;
}

.hero-tag {
    color: var(--accent-red);
    font-size: 0.725rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.tech-sample-pill {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.675rem;
    font-weight: 600;
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
}

.hero-title {
    font-size: 2.25rem;
    font-weight: 800;
    line-height: 1.15;
    margin-bottom: 0.4rem;
    letter-spacing: -0.025em;
}

.hero-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-secondary);
    font-size: 0.85rem;
    margin-bottom: 0.85rem;
    flex-wrap: wrap;
}

.meta-tag {
    background-color: var(--accent-red-subtle);
    color: var(--accent-red);
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.725rem;
}

.meta-separator {
    color: var(--text-muted);
}

.hero-description {
    color: var(--text-secondary);
    font-size: 0.925rem;
    margin-bottom: 1.25rem;
    line-height: 1.55;
}

.hero-actions {
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 1.1rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.875rem;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background-color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
    background-color: var(--accent-red);
    color: #ffffff;
}

.btn-primary:hover {
    background-color: var(--accent-red-hover);
}

.btn-secondary {
    background-color: var(--bg-elevated);
    color: var(--text-primary);
    border-color: var(--border-color);
}

.btn-secondary:hover {
    background-color: var(--bg-hover);
}

/* Catalogue Section */
.section-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 1rem;
}

.section-title {
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: -0.015em;
}

.item-count {
    color: var(--text-muted);
    font-size: 0.825rem;
}

.toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 0.75rem 1rem;
    border-radius: var(--radius-md);
    align-items: center;
    justify-content: space-between;
}

.search-box {
    position: relative;
    flex: 1;
    min-width: 250px;
    display: flex;
    align-items: center;
}

.search-icon {
    position: absolute;
    left: 0.75rem;
    font-size: 0.85rem;
    color: var(--text-muted);
    pointer-events: none;
}

.search-box input {
    width: 100%;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.5rem 2.2rem 0.5rem 2.2rem;
    border-radius: var(--radius-sm);
    outline: none;
    transition: border-color 0.15s ease;
}

.search-box input:focus {
    border-color: var(--border-focus);
}

.clear-btn {
    position: absolute;
    right: 0.6rem;
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 0.95rem;
    cursor: pointer;
}

.clear-btn:hover {
    color: var(--text-primary);
}

.filter-group {
    display: flex;
    gap: 0.75rem;
    align-items: center;
    flex-wrap: wrap;
}

.type-tabs {
    display: flex;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    padding: 2px;
}

.type-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    padding: 0.35rem 0.85rem;
    border-radius: var(--radius-sm);
    font-size: 0.825rem;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease;
}

.type-tab.active {
    background-color: var(--bg-hover);
    color: var(--text-primary);
    font-weight: 600;
}

.select-wrapper select {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.4rem 0.85rem;
    border-radius: var(--radius-sm);
    outline: none;
    cursor: pointer;
    font-size: 0.825rem;
}

.select-wrapper select:focus {
    border-color: var(--border-focus);
}

/* UI States */
.state-view {
    text-align: center;
    padding: 3rem 1rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
}

.state-icon {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.state-view h3 {
    font-size: 1.05rem;
    margin-bottom: 0.3rem;
}

.state-view p {
    color: var(--text-secondary);
    font-size: 0.875rem;
    margin-bottom: 1rem;
}

.spinner {
    width: 32px;
    height: 32px;
    border: 3px solid var(--border-color);
    border-top-color: var(--accent-red);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 1rem auto;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Media Cards Grid - Responsive Breakdown */
.media-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
}

@media (max-width: 1199px) {
    .media-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 899px) {
    .media-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 599px) {
    .media-grid {
        grid-template-columns: repeat(1, 1fr);
    }
}

/* Media Card Styling */
.media-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    height: 100%;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.media-card:hover {
    transform: translateY(-2px);
    border-color: var(--text-muted);
}

.card-thumb-wrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    background-color: var(--bg-elevated);
    overflow: hidden;
    cursor: pointer;
}

.card-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.25s ease;
}

.card-thumb-wrapper:hover .card-thumb {
    transform: scale(1.04);
}

.card-badge {
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
    background-color: rgba(18, 18, 20, 0.9);
    border: 1px solid var(--border-color);
    color: var(--accent-red);
    font-size: 0.675rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.125rem 0.45rem;
    border-radius: var(--radius-sm);
    letter-spacing: 0.04em;
}

.tech-sample-tag {
    position: absolute;
    bottom: 0.5rem;
    right: 0.5rem;
    background-color: rgba(18, 18, 20, 0.85);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.625rem;
    padding: 0.1rem 0.35rem;
    border-radius: var(--radius-sm);
}

.card-content {
    padding: 0.95rem;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.card-title {
    font-size: 0.975rem;
    font-weight: 700;
    line-height: 1.35;
    margin-bottom: 0.25rem;
    color: var(--text-primary);
    cursor: pointer;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    max-height: 2.7em;
}

.card-title:hover {
    color: var(--accent-red);
}

.card-subtitle {
    color: var(--text-secondary);
    font-size: 0.825rem;
    margin-bottom: 0.4rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.card-meta {
    display: flex;
    gap: 0.4rem;
    align-items: center;
    color: var(--text-muted);
    font-size: 0.775rem;
    margin-bottom: 0.85rem;
}

.card-actions {
    margin-top: auto;
    display: flex;
    gap: 0.4rem;
}

.card-actions .btn {
    flex: 1;
    padding: 0.4rem 0.5rem;
    font-size: 0.8rem;
}

/* Application Footer */
.app-footer {
    background-color: var(--bg-surface);
    border-top: 1px solid var(--border-color);
    padding: 1.5rem;
    margin-top: auto;
}

.footer-container {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.footer-brand {
    font-weight: 700;
    font-size: 0.9rem;
    color: var(--text-primary);
}

.footer-disclaimer {
    color: var(--text-muted);
    font-size: 0.775rem;
    line-height: 1.5;
}

/* Details Dialog Modal */
.details-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background-color: var(--bg-surface);
    color: var(--text-primary);
    max-width: 580px;
    width: 90%;
    margin: auto;
    padding: 0;
    box-shadow: var(--shadow-dialog);
}

.details-dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(2px);
}

.dialog-content {
    position: relative;
    padding: 1.75rem;
}

.dialog-close {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    width: 32px;
    height: 32px;
    border-radius: 50%;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10;
}

.dialog-close:hover {
    color: var(--text-primary);
    border-color: var(--text-muted);
}

.dialog-header-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
}

.dialog-title {
    font-size: 1.5rem;
    font-weight: 800;
    line-height: 1.25;
    margin-bottom: 0.2rem;
}

.dialog-artist {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 0.85rem;
}

.dialog-description {
    color: var(--text-secondary);
    font-size: 0.875rem;
    line-height: 1.6;
    margin-bottom: 1.1rem;
    background-color: var(--bg-elevated);
    padding: 0.85rem 1rem;
    border-radius: var(--radius-sm);
    border-left: 3px solid var(--accent-red);
}

.dialog-info-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.75rem;
    margin-bottom: 1.25rem;
}

.info-item {
    background-color: var(--bg-elevated);
    padding: 0.45rem 0.65rem;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
}

.info-label {
    font-size: 0.675rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.info-value {
    font-size: 0.825rem;
    font-weight: 600;
}

/* Auth Dialog Modal */
.auth-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background-color: var(--bg-surface);
    color: var(--text-primary);
    max-width: 440px;
    width: 90%;
    margin: auto;
    padding: 0;
    box-shadow: var(--shadow-dialog);
}

.auth-dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.85);
    backdrop-filter: blur(4px);
}

.auth-dialog-content {
    position: relative;
    padding: 2.25rem 2rem;
}

.auth-title {
    font-size: 1.75rem;
    font-weight: 800;
    margin-bottom: 1.5rem;
}

.auth-form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.auth-form .form-group input {
    width: 100%;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.85rem 1rem;
    border-radius: var(--radius-sm);
    outline: none;
}

.auth-form .form-group input:focus {
    border-color: var(--accent-red);
}

.btn-auth-submit {
    width: 100%;
    padding: 0.85rem;
    font-size: 1rem;
    margin-top: 0.5rem;
}

.auth-help {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.8rem;
    color: var(--text-muted);
}

.auth-demo-note {
    font-size: 0.775rem;
    color: var(--text-muted);
    background-color: var(--bg-elevated);
    padding: 0.65rem 0.85rem;
    border-radius: var(--radius-sm);
    margin-top: 1rem;
    border-left: 3px solid var(--accent-red);
}

/* Video Player Modal Styling */
.video-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background-color: #121214;
    color: var(--text-primary);
    max-width: 960px;
    width: 92%;
    margin: auto;
    padding: 0;
    box-shadow: var(--shadow-dialog);
    overflow: hidden;
}

.video-dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.85);
    backdrop-filter: blur(4px);
}

.video-dialog-content {
    position: relative;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.video-modal-header {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.video-header-top {
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.video-modal-title {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--text-primary);
    letter-spacing: -0.02em;
}

.video-wrapper {
    width: 100%;
    aspect-ratio: 16/9;
    background-color: #000000;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.video-wrapper video {
    width: 100%;
    height: 100%;
    object-fit: contain;
    background-color: #000000;
    outline: none;
}

.video-modal-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 0.25rem;
}

/* Audio Player Bar */
.audio-player-bar {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background-color: var(--bg-surface);
    border-top: 1px solid var(--border-color);
    padding: 0.65rem 1.5rem;
    z-index: 90;
    transition: transform 0.2s ease;
}

.audio-player-bar.minimized {
    transform: translateY(calc(100% - 10px));
}

.player-container {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.player-toggle-btn {
    display: none; /* Mobile toggle button */
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 0.8rem;
    cursor: pointer;
}

.player-track-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    min-width: 220px;
    max-width: 300px;
}

.track-thumb {
    width: 38px;
    height: 38px;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    flex-shrink: 0;
}

.track-text {
    overflow: hidden;
}

.track-title {
    font-size: 0.85rem;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.track-artist {
    font-size: 0.75rem;
    color: var(--text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.player-controls {
    flex: 1;
    display: flex;
    justify-content: center;
}

.player-controls audio {
    width: 100%;
    max-width: 480px;
    height: 36px;
}

.player-status {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.725rem;
    color: var(--text-muted);
    min-width: 140px;
    justify-content: flex-end;
}

.event-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background-color: var(--text-muted);
}

.event-dot.active {
    background-color: var(--accent-red);
    box-shadow: 0 0 6px var(--accent-red);
}

/* Responsive Styles for Tablet and Mobile */
@media (max-width: 768px) {
    .nav-container {
        flex-wrap: wrap;
        padding: 0.65rem 1rem;
    }

    .brand-logo-img {
        height: 38px;
    }

    .landing-hero {
        padding: 3rem 1rem 3.5rem 1rem;
    }

    .landing-title {
        font-size: 1.95rem;
    }

    .landing-subtitle {
        font-size: 1.1rem;
    }

    .landing-email-form {
        flex-direction: column;
    }

    .btn-get-started {
        width: 100%;
    }

    .hero-section {
        padding: 1.5rem 1.25rem;
    }

    .hero-title {
        font-size: 1.75rem;
    }

    .toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .search-box {
        min-width: 100%;
    }

    .filter-group {
        flex-direction: column;
        align-items: stretch;
    }

    .type-tabs {
        justify-content: center;
    }

    .select-wrapper select {
        width: 100%;
    }

    .video-dialog {
        width: 96%;
    }

    .video-dialog-content {
        padding: 1rem;
    }

    .video-modal-title {
        font-size: 1.2rem;
    }

    .player-toggle-btn {
        display: block;
    }

    .player-container {
        flex-direction: column;
        align-items: stretch;
        gap: 0.4rem;
    }

    .player-track-info {
        max-width: 100%;
    }

    .player-status {
        justify-content: flex-start;
    }

    body {
        padding-bottom: 140px;
    }
}

/**
 * StreamWave Entertainment - Frontend Application Logic
 * Academic Serverless Prototype with Netflix-Style Landing Page & Auth Modal
 */

(function () {
    'use strict';

    // App State
    const state = {
        media: [],
        activeType: '',
        activeGenre: '',
        searchQuery: '',
        currentTrack: null,
        activeVideoMovie: null,
        lastFocusedElement: null,
        loggedVideoEvents: new Set(),
        sessionId: 'sess-' + Math.random().toString(36).substring(2, 9),
        playerMinimized: false,
        userEmail: ''
    };

    // DOM Elements
    const elements = {
        searchInput: document.getElementById('search-input'),
        clearSearchBtn: document.getElementById('clear-search'),
        typeTabs: document.querySelectorAll('.type-tab'),
        genreSelect: document.getElementById('genre-select'),
        itemCount: document.getElementById('item-count'),

        // Views
        loadingState: document.getElementById('loading-state'),
        errorState: document.getElementById('error-state'),
        errorMessage: document.getElementById('error-message'),
        emptyState: document.getElementById('empty-state'),
        mediaGrid: document.getElementById('media-grid'),

        // Auth Modal
        authDialog: document.getElementById('auth-dialog'),

        // Details Modal
        detailsDialog: document.getElementById('details-dialog'),
        closeDialogBtn: document.getElementById('close-dialog'),
        dialogBody: document.getElementById('dialog-body'),

        // Video Modal
        videoDialog: document.getElementById('video-dialog'),
        closeVideoBtn: document.getElementById('close-video-btn'),
        closeVideoX: document.getElementById('close-video-x'),
        videoModalTitle: document.getElementById('video-modal-title'),
        videoElement: document.getElementById('html5-video'),
        videoSource: document.getElementById('video-source'),
        videoReplayBtn: document.getElementById('video-replay-btn'),

        // Audio Player
        audioBar: document.getElementById('audio-player-bar'),
        playerToggleBtn: document.getElementById('player-toggle-btn'),
        audioElement: document.getElementById('html5-audio'),
        audioSource: document.getElementById('audio-source'),
        playerThumb: document.getElementById('player-thumb'),
        playerTitle: document.getElementById('player-title'),
        playerArtist: document.getElementById('player-artist'),
        eventLogText: document.getElementById('event-log-text'),
        eventDot: document.querySelector('.event-dot')
    };

    /**
     * Initializes event listeners and fetches initial media list
     */
    function init() {
        bindEvents();
        fetchMedia();
    }

    /**
     * Binds user interaction listeners
     */
    function bindEvents() {
        // Search input with debounce
        let searchTimeout;
        elements.searchInput.addEventListener('input', (e) => {
            state.searchQuery = e.target.value.trim();
            elements.clearSearchBtn.style.display = state.searchQuery ? 'block' : 'none';
            clearTimeout(searchTimeout);
            searchTimeout = setTimeout(() => fetchMedia(), 250);
        });

        elements.clearSearchBtn.addEventListener('click', () => {
            elements.searchInput.value = '';
            state.searchQuery = '';
            elements.clearSearchBtn.style.display = 'none';
            fetchMedia();
        });

        // Type tabs
        elements.typeTabs.forEach((tab) => {
            tab.addEventListener('click', () => {
                elements.typeTabs.forEach((t) => {
                    t.classList.remove('active');
                    t.setAttribute('aria-selected', 'false');
                });
                tab.classList.add('active');
                tab.setAttribute('aria-selected', 'true');
                state.activeType = tab.getAttribute('data-type');
                fetchMedia();
            });
        });

        // Genre filter select
        elements.genreSelect.addEventListener('change', (e) => {
            state.activeGenre = e.target.value;
            fetchMedia();
        });

        // Details Modal close button
        elements.closeDialogBtn.addEventListener('click', () => {
            elements.detailsDialog.close();
        });

        // Close details modal on backdrop click
        elements.detailsDialog.addEventListener('click', (e) => {
            const rect = elements.detailsDialog.getBoundingClientRect();
            const isInDialog = (
                rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                rect.left <= e.clientX && e.clientX <= rect.left + rect.width
            );
            if (!isInDialog) {
                elements.detailsDialog.close();
            }
        });

        // Close Auth modal on backdrop click
        if (elements.authDialog) {
            elements.authDialog.addEventListener('click', (e) => {
                const rect = elements.authDialog.getBoundingClientRect();
                const isInDialog = (
                    rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                    rect.left <= e.clientX && e.clientX <= rect.left + rect.width
                );
                if (!isInDialog) {
                    closeAuthModal();
                }
            });
        }

        // Video Modal Close Handlers
        if (elements.closeVideoBtn) {
            elements.closeVideoBtn.addEventListener('click', closeVideoModal);
        }
        if (elements.closeVideoX) {
            elements.closeVideoX.addEventListener('click', closeVideoModal);
        }

        // Close video modal on backdrop click
        if (elements.videoDialog) {
            elements.videoDialog.addEventListener('click', (e) => {
                const rect = elements.videoDialog.getBoundingClientRect();
                const isInDialog = (
                    rect.top <= e.clientY && e.clientY <= rect.top + rect.height &&
                    rect.left <= e.clientX && e.clientX <= rect.left + rect.width
                );
                if (!isInDialog) {
                    closeVideoModal();
                }
            });
        }

        // Video ended listener -> show Replay button
        if (elements.videoElement) {
            elements.videoElement.addEventListener('ended', () => {
                if (elements.videoReplayBtn) {
                    elements.videoReplayBtn.style.display = 'inline-flex';
                }
            });

            // Video play listener -> trigger POST /api/play-events (once per movie playback start)
            elements.videoElement.addEventListener('play', () => {
                if (state.activeVideoMovie) {
                    const movieId = state.activeVideoMovie.id;
                    if (!state.loggedVideoEvents.has(movieId)) {
                        state.loggedVideoEvents.add(movieId);
                        logPlayEvent(movieId);
                    }
                }
            });
        }

        // Replay button click handler
        if (elements.videoReplayBtn) {
            elements.videoReplayBtn.addEventListener('click', () => {
                elements.videoReplayBtn.style.display = 'none';
                if (elements.videoElement) {
                    elements.videoElement.currentTime = 0;
                    elements.videoElement.play().catch(err => console.warn('Replay play error:', err));
                }
            });
        }

        // Global Escape key listener for dialog accessibility
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                if (elements.videoDialog && elements.videoDialog.open) {
                    closeVideoModal();
                } else if (elements.detailsDialog && elements.detailsDialog.open) {
                    elements.detailsDialog.close();
                } else if (elements.authDialog && elements.authDialog.open) {
                    closeAuthModal();
                }
            }
        });

        // Player mobile minimize toggle
        if (elements.playerToggleBtn) {
            elements.playerToggleBtn.addEventListener('click', () => {
                state.playerMinimized = !state.playerMinimized;
                elements.audioBar.classList.toggle('minimized', state.playerMinimized);
                elements.playerToggleBtn.textContent = state.playerMinimized ? '▲' : '▼';
                elements.playerToggleBtn.setAttribute('aria-label', state.playerMinimized ? 'Expand audio player' : 'Minimize audio player');
            });
        }

        // Audio element playback listener to trigger POST /api/play-events for music
        elements.audioElement.addEventListener('play', () => {
            if (state.currentTrack) {
                logPlayEvent(state.currentTrack.id);
            }
        });
    }

    /**
     * Handles Netflix-style Get Started form submission
     */
    function handleGetStarted(e) {
        if (e) e.preventDefault();
        const emailInput = document.getElementById('landing-email');
        if (emailInput && emailInput.value) {
            state.userEmail = emailInput.value.trim();
        }

        const catalogueSection = document.getElementById('catalogue');
        if (catalogueSection) {
            catalogueSection.scrollIntoView({ behavior: 'smooth' });
        }

        updateEventBadge(state.userEmail ? `Welcome ${state.userEmail.split('@')[0]}!` : 'Exploring Catalogue', true);
    }

    /**
     * Opens Sign In Modal
     */
    function openAuthModal() {
        if (elements.authDialog) {
            elements.authDialog.showModal();
        }
    }

    /**
     * Closes Sign In Modal
     */
    function closeAuthModal() {
        if (elements.authDialog && elements.authDialog.open) {
            elements.authDialog.close();
        }
    }

    /**
     * Handles Sign In submission
     */
    function handleSignIn(e) {
        if (e) e.preventDefault();
        const emailInput = document.getElementById('auth-email');
        if (emailInput && emailInput.value) {
            state.userEmail = emailInput.value.trim();
        }

        closeAuthModal();

        const catalogueSection = document.getElementById('catalogue');
        if (catalogueSection) {
            catalogueSection.scrollIntoView({ behavior: 'smooth' });
        }

        updateEventBadge(`Signed In (${state.userEmail ? state.userEmail.split('@')[0] : 'Demo User'})`, true);
    }

    /**
     * Fetches media items from FastAPI backend /api/media endpoint
     */
    async function fetchMedia() {
        showView('loading');

        try {
            const params = new URLSearchParams();
            if (state.searchQuery) params.append('query', state.searchQuery);
            if (state.activeType) params.append('type', state.activeType);
            if (state.activeGenre) params.append('genre', state.activeGenre);

            const url = `/api/media${params.toString() ? '?' + params.toString() : ''}`;
            const response = await fetch(url);

            if (!response.ok) {
                throw new Error(`Server returned HTTP ${response.status}`);
            }

            state.media = await response.json();
            renderMediaGrid();
        } catch (err) {
            console.error('Error fetching media:', err);
            elements.errorMessage.textContent = err.message || 'Failed to connect to StreamWave API.';
            showView('error');
        }
    }

    /**
     * Renders media items in card grid with StreamWave play symbol ("▶ Watch" / "▶ Play")
     */
    function renderMediaGrid() {
        elements.itemCount.textContent = `${state.media.length} item${state.media.length === 1 ? '' : 's'}`;

        if (state.media.length === 0) {
            showView('empty');
            return;
        }

        elements.mediaGrid.innerHTML = state.media.map((item) => {
            const isMovie = item.type === 'movie';
            const playLabel = isMovie ? 'Watch' : 'Play';
            const playIcon = '▶';
            const clickHandler = isMovie
                ? `window.streamWaveApp.playMoviePreview('${item.id}', this)`
                : `window.streamWaveApp.playMedia('${item.id}')`;
            const escapedTitle = escapeHtml(item.title);

            return `
                <article class="media-card" data-id="${item.id}">
                    <div class="card-thumb-wrapper" onclick="window.streamWaveApp.openDetails('${item.id}', this)" title="View details for ${escapedTitle}">
                        <img class="card-thumb" src="${item.cover_image || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=600&q=80'}" alt="${escapedTitle}" loading="lazy">
                        <span class="card-badge">${escapeHtml(item.type)}</span>
                        <span class="tech-sample-tag">5-sec technical preview</span>
                    </div>
                    <div class="card-content">
                        <h3 class="card-title" title="${escapedTitle}" onclick="window.streamWaveApp.openDetails('${item.id}', this)">${escapedTitle}</h3>
                        <div class="card-subtitle">${escapeHtml(item.artist_or_director)}</div>
                        <div class="card-meta">
                            <span>${item.year}</span>
                            <span>•</span>
                            <span>${escapeHtml(item.genre)}</span>
                            <span>•</span>
                            <span>${escapeHtml(item.duration)}</span>
                        </div>
                        <div class="card-actions">
                            <button class="btn btn-primary" onclick="${clickHandler}" aria-label="${playLabel} ${escapedTitle}">
                                ${playIcon} ${playLabel}
                            </button>
                            <button class="btn btn-secondary" onclick="window.streamWaveApp.openDetails('${item.id}', this)" aria-label="View details for ${escapedTitle}">
                                ℹ Details
                            </button>
                        </div>
                    </div>
                </article>
            `;
        }).join('');

        showView('grid');
    }

    /**
     * Switch view state (loading, error, empty, grid)
     */
    function showView(viewName) {
        elements.loadingState.style.display = viewName === 'loading' ? 'block' : 'none';
        elements.errorState.style.display = viewName === 'error' ? 'block' : 'none';
        elements.emptyState.style.display = viewName === 'empty' ? 'block' : 'none';
        elements.mediaGrid.style.display = viewName === 'grid' ? 'grid' : 'none';
    }

    /**
     * Opens professional video player modal for movie previews
     */
    async function playMoviePreview(id, triggerElement) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.activeVideoMovie = item;
        state.lastFocusedElement = triggerElement || document.activeElement;

        // Populate title
        elements.videoModalTitle.textContent = item.title;

        // Set video source to static preview MP4 URL
        const videoUrl = item.preview_url || item.media_url || '/media/streamwave-preview.mp4';
        elements.videoSource.src = videoUrl;
        elements.videoElement.load();

        // Reset replay button
        if (elements.videoReplayBtn) {
            elements.videoReplayBtn.style.display = 'none';
        }

        // Lock scroll & show modal
        document.body.style.overflow = 'hidden';
        elements.videoDialog.showModal();

        // Start playback after user click interaction
        try {
            await elements.videoElement.play();
        } catch (e) {
            console.warn('Video play prevented or interrupted:', e);
        }

        // Log playback event
        if (!state.loggedVideoEvents.has(id)) {
            state.loggedVideoEvents.add(id);
            logPlayEvent(id);
        }
    }

    /**
     * Closes video modal, resets playback position, and restores focus/scrolling
     */
    function closeVideoModal() {
        if (elements.videoElement) {
            elements.videoElement.pause();
            elements.videoElement.currentTime = 0;
        }

        state.activeVideoMovie = null;
        document.body.style.overflow = '';

        if (elements.videoDialog && elements.videoDialog.open) {
            elements.videoDialog.close();
        }

        // Restore keyboard focus to triggering element
        if (state.lastFocusedElement && typeof state.lastFocusedElement.focus === 'function') {
            state.lastFocusedElement.focus();
        }
    }

    /**
     * Plays music item audio file using HTML5 Audio Player
     */
    async function playMedia(id) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        // If item is a movie, delegate to playMoviePreview
        if (item.type === 'movie') {
            playMoviePreview(id);
            return;
        }

        state.currentTrack = item;
        elements.playerTitle.textContent = item.title;
        elements.playerArtist.textContent = `${item.artist_or_director} (${item.genre})`;
        elements.playerThumb.textContent = '🎵';

        // Unminimize player bar if minimized
        if (state.playerMinimized) {
            state.playerMinimized = false;
            elements.audioBar.classList.remove('minimized');
            if (elements.playerToggleBtn) elements.playerToggleBtn.textContent = '▼';
        }

        // Set audio source to static file URL (defaults to /media/demo.wav for demo)
        const audioUrl = item.media_url || '/media/demo.wav';
        elements.audioSource.src = audioUrl;
        elements.audioElement.load();

        try {
            await elements.audioElement.play();
        } catch (e) {
            console.warn('Autoplay prevented or failed:', e);
        }

        // Trigger POST /api/play-events
        logPlayEvent(id);
    }

    /**
     * Fetches a single media item by ID
     */
    async function fetchSingleItem(id) {
        try {
            const res = await fetch(`/api/media/${id}`);
            if (res.ok) return await res.json();
        } catch (e) {
            console.error('Error fetching item detail:', e);
        }
        return null;
    }

    /**
     * Sends playback event log to POST /api/play-events
     */
    async function logPlayEvent(mediaId) {
        updateEventBadge('Logging...', true);
        try {
            const payload = {
                media_id: mediaId,
                session_id: state.sessionId,
                client_timestamp: new Date().toISOString()
            };

            const res = await fetch('/api/play-events', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                const data = await res.json();
                updateEventBadge(`Event Logged (${data.event.server_timestamp.slice(11, 19)} UTC)`, false);
            } else {
                updateEventBadge('Event Log Error', false);
            }
        } catch (err) {
            console.error('Play event error:', err);
            updateEventBadge('Event Log Failed', false);
        }
    }

    /**
     * Updates status dot badge near audio player
     */
    function updateEventBadge(text, isActive) {
        elements.eventLogText.textContent = text;
        if (isActive) {
            elements.eventDot.classList.add('active');
        } else {
            elements.eventDot.classList.remove('active');
        }
    }

    /**
     * Opens accessible details dialog
     */
    async function openDetails(id, triggerElement) {
        const item = state.media.find(m => m.id === id) || await fetchSingleItem(id);
        if (!item) return;

        state.lastFocusedElement = triggerElement || document.activeElement;
        const isMovie = item.type === 'movie';
        const playLabel = isMovie ? 'Watch' : 'Play';
        const playIcon = '▶';
        const clickHandler = isMovie
            ? `window.streamWaveApp.playMoviePreview('${item.id}'); document.getElementById('details-dialog').close();`
            : `window.streamWaveApp.playMedia('${item.id}'); document.getElementById('details-dialog').close();`;

        elements.dialogBody.innerHTML = `
            <div class="dialog-header-meta">
                <span class="meta-tag">${escapeHtml(item.type)}</span>
                <span class="meta-separator">•</span>
                <span style="color: var(--text-secondary); font-size: 0.85rem;">${item.year}</span>
                <span class="meta-separator">•</span>
                <span class="tech-sample-pill">${isMovie ? '5-sec MP4 preview' : 'Technical audio sample'}</span>
            </div>
            <h2 id="dialog-title" class="dialog-title">${escapeHtml(item.title)}</h2>
            <div class="dialog-artist">By ${escapeHtml(item.artist_or_director)}</div>
            <p id="dialog-desc" class="dialog-description">${escapeHtml(item.description)}</p>

            <div class="dialog-info-grid">
                <div class="info-item">
                    <div class="info-label">Genre</div>
                    <div class="info-value">${escapeHtml(item.genre)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Duration</div>
                    <div class="info-value">${escapeHtml(item.duration)}</div>
                </div>
                <div class="info-item">
                    <div class="info-label">Media ID</div>
                    <div class="info-value">${escapeHtml(item.id)}</div>
                </div>
            </div>

            <div class="dialog-actions" style="display: flex; gap: 0.75rem;">
                <button class="btn btn-primary" onclick="${clickHandler}">
                    ${playIcon} ${playLabel}
                </button>
            </div>
        `;

        elements.detailsDialog.showModal();
    }

    /**
     * Resets filter parameters
     */
    function resetFilters() {
        state.searchQuery = '';
        state.activeType = '';
        state.activeGenre = '';
        elements.searchInput.value = '';
        elements.genreSelect.value = '';
        elements.clearSearchBtn.style.display = 'none';
        elements.typeTabs.forEach((tab, index) => {
            tab.classList.toggle('active', index === 0);
            tab.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
        });
        fetchMedia();
    }

    /**
     * Basic HTML escaping to prevent XSS
     */
    function escapeHtml(str) {
        if (!str) return '';
        return str
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    // Expose global methods for inline button onclick handlers
    window.streamWaveApp = {
        fetchMedia,
        playMedia,
        playMoviePreview,
        openDetails,
        closeVideoModal,
        openAuthModal,
        closeAuthModal,
        handleGetStarted,
        handleSignIn,
        resetFilters
    };

    // Initialize on DOM load
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

