/* ==========================================================================
   StreamWave Entertainment - Responsive Media Platform Stylesheet
   Dark Graphite Theme with Restrained Red Accent
   ========================================================================== */

:root {
    --bg-base: #121214;
    --bg-surface: #18181c;
    --bg-elevated: #222228;
    --bg-hover: #2e2e36;

    --border-color: #2e2e38;
    --border-focus: #e50914;

    --text-primary: #f4f4f6;
    --text-secondary: #a0a0ab;
    --text-muted: #6e6e7a;

    --accent-red: #e50914;
    --accent-red-hover: #b80710;
    --accent-red-subtle: rgba(229, 9, 20, 0.15);

    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --radius-sm: 4px;
    --radius-md: 6px;

    --shadow-card: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-dialog: 0 16px 32px rgba(0, 0, 0, 0.7);
}

/* Base Resets */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    overflow-x: hidden;
    scroll-behavior: smooth;
}

body {
    background-color: var(--bg-base);
    color: var(--text-primary);
    font-family: var(--font-family);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    overflow-x: hidden;
}

.library-body {
    padding-bottom: 110px; /* Space so fixed audio player never obscures footer */
}

a {
    color: inherit;
    text-decoration: none;
}

button, input, select {
    font-family: inherit;
    font-size: inherit;
}

/* Accessibility Focus Visible */
*:focus-visible {
    outline: 2px solid var(--accent-red);
    outline-offset: 2px;
}

/* Navigation Bar */
.navbar {
    background-color: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav-container {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0.85rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-weight: 800;
    font-size: 1.2rem;
    letter-spacing: -0.02em;
    color: var(--text-primary);
}

.brand-logo-img {
    height: 48px;
    max-height: 52px;
    width: auto;
    object-fit: contain;
    display: block;
    transition: transform 0.15s ease;
}

.brand-logo-img:hover {
    transform: scale(1.02);
}

.footer-logo-img {
    height: 36px;
    width: auto;
    object-fit: contain;
    display: block;
}

.nav-links {
    display: flex;
    gap: 1.25rem;
    align-items: center;
}

.nav-link {
    color: var(--text-secondary);
    font-size: 0.875rem;
    font-weight: 500;
    transition: color 0.15s ease;
}

.nav-link:hover, .nav-link.active {
    color: var(--text-primary);
}

.developer-link {
    color: var(--accent-red);
    font-weight: 600;
    font-size: 0.8rem;
    background-color: var(--accent-red-subtle);
    padding: 0.2rem 0.55rem;
    border-radius: var(--radius-sm);
    border: 1px solid rgba(229, 9, 20, 0.3);
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.btn-signin-nav {
    font-size: 0.85rem;
    padding: 0.35rem 0.95rem;
}

.member-nav-controls {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.member-badge {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    padding: 0.25rem 0.65rem;
    border-radius: var(--radius-sm);
    font-size: 0.775rem;
    font-weight: 600;
    color: var(--text-primary);
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.pulse-dot {
    width: 7px;
    height: 7px;
    background-color: #10b981;
    border-radius: 50%;
    box-shadow: 0 0 8px #10b981;
}

/* Landing Page Hero Section */
.landing-main {
    flex: 1;
}

.landing-hero {
    position: relative;
    padding: 5.5rem 1.5rem 6rem 1.5rem;
    background-color: #0b0b0d;
    background-image: radial-gradient(circle at center, rgba(229, 9, 20, 0.22) 0%, rgba(18, 18, 20, 0.96) 75%), url('https://images.unsplash.com/photo-1574375927938-d5a98e8ffe85?auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
    border-bottom: 1px solid var(--border-color);
    text-align: center;
    overflow: hidden;
}

.hero-bg-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, rgba(18, 18, 20, 0.85) 0%, rgba(18, 18, 20, 0.65) 50%, rgba(18, 18, 20, 0.98) 100%);
    pointer-events: none;
}

.landing-hero-content {
    position: relative;
    z-index: 2;
    max-width: 820px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.15rem;
}

.academic-badge-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    background-color: rgba(24, 24, 28, 0.92);
    border: 1px solid var(--border-color);
    padding: 0.25rem 0.8rem;
    border-radius: 50px;
    font-size: 0.725rem;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.landing-hero-title {
    font-size: 3.1rem;
    font-weight: 900;
    line-height: 1.12;
    letter-spacing: -0.035em;
    color: #ffffff;
}

.landing-hero-subtitle {
    font-size: 1.4rem;
    font-weight: 500;
    color: var(--text-primary);
}

.landing-hero-instruction {
    font-size: 1.05rem;
    color: var(--text-secondary);
    margin-top: 0.2rem;
}

.landing-start-form {
    width: 100%;
    max-width: 620px;
    margin-top: 0.5rem;
}

.input-action-group {
    display: flex;
    gap: 0.5rem;
    width: 100%;
}

.input-action-group input {
    flex: 1;
    background-color: rgba(22, 22, 26, 0.92);
    border: 1px solid rgba(255, 255, 255, 0.35);
    color: #ffffff;
    padding: 0.95rem 1.25rem;
    border-radius: var(--radius-sm);
    font-size: 1rem;
    outline: none;
    transition: border-color 0.15s ease;
}

.input-action-group input:focus {
    border-color: var(--accent-red);
}

.btn-get-started {
    font-size: 1.2rem;
    font-weight: 700;
    padding: 0.95rem 1.75rem;
    white-space: nowrap;
    border-radius: var(--radius-sm);
}

.btn-get-started .chevron {
    font-size: 1.4rem;
    font-weight: 400;
    margin-left: 0.25rem;
}

/* Landing Page Sections */
.landing-section {
    padding: 4.5rem 1.5rem;
    border-bottom: 1px solid var(--border-color);
}

.section-container {
    max-width: 1140px;
    margin: 0 auto;
}

.landing-section-title {
    font-size: 2rem;
    font-weight: 800;
    text-align: center;
    margin-bottom: 2.5rem;
    letter-spacing: -0.02em;
}

.section-subtitle {
    text-align: center;
    color: var(--text-secondary);
    font-size: 1rem;
    margin-top: -1.75rem;
    margin-bottom: 2.25rem;
}

/* Benefits Grid */
.benefits-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
}

.benefit-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 1.75rem 1.25rem;
    border-radius: var(--radius-md);
    text-align: center;
}

.benefit-icon {
    font-size: 2.25rem;
    margin-bottom: 0.85rem;
}

.benefit-card h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.benefit-card p {
    font-size: 0.875rem;
    color: var(--text-secondary);
    line-height: 1.5;
}

/* Steps Grid (How It Works) */
.steps-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.75rem;
}

.step-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 2rem 1.5rem;
    border-radius: var(--radius-md);
    position: relative;
}

.step-number {
    width: 42px;
    height: 42px;
    background-color: var(--accent-red);
    color: #ffffff;
    font-weight: 800;
    font-size: 1.25rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1rem;
}

.step-card h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 0.4rem;
}

.step-card p {
    font-size: 0.875rem;
    color: var(--text-secondary);
    line-height: 1.5;
}

/* Payment Badges */
.payment-badges-row {
    display: flex;
    justify-content: center;
    gap: 1.5rem;
    margin-bottom: 1.75rem;
    flex-wrap: wrap;
}

.payment-badge {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 0.75rem 1.75rem;
    border-radius: var(--radius-md);
    font-weight: 700;
    font-size: 1.1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.notice-pill {
    display: inline-block;
    background-color: var(--accent-red-subtle);
    border: 1px solid rgba(229, 9, 20, 0.4);
    color: var(--text-primary);
    padding: 0.5rem 1.25rem;
    border-radius: var(--radius-sm);
    font-size: 0.85rem;
    font-weight: 600;
}

/* Checkout Page Styling */
.checkout-main {
    max-width: 1040px;
    width: 100%;
    margin: 2rem auto;
    padding: 0 1.5rem;
    flex: 1;
}

.simulation-alert-banner {
    background-color: #2b1d05;
    border: 1px solid #d97706;
    color: #fef3c7;
    padding: 1rem 1.25rem;
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    gap: 0.85rem;
    margin-bottom: 1.75rem;
}

.alert-icon {
    font-size: 1.5rem;
}

.alert-text strong {
    font-size: 0.95rem;
    letter-spacing: 0.04em;
}

.alert-text p {
    font-size: 0.85rem;
    margin-top: 0.15rem;
    opacity: 0.9;
}

.checkout-grid {
    display: grid;
    grid-template-columns: 1fr 1.35fr;
    gap: 1.75rem;
}

.summary-box, .payment-form-box {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    padding: 1.75rem;
}

.box-title {
    font-size: 1.25rem;
    font-weight: 800;
    margin-bottom: 1.25rem;
    letter-spacing: -0.015em;
}

.plan-card {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    padding: 1.25rem;
    border-radius: var(--radius-sm);
}

.plan-badge {
    color: var(--accent-red);
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.08em;
}

.plan-name {
    font-size: 1.35rem;
    font-weight: 800;
    margin-top: 0.15rem;
}

.plan-price {
    font-size: 1.75rem;
    font-weight: 900;
    color: var(--text-primary);
    margin: 0.65rem 0 1rem 0;
}

.price-period {
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--text-muted);
}

.plan-benefits-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.check-icon {
    color: #10b981;
    font-weight: 800;
    margin-right: 0.35rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-label {
    display: block;
    font-size: 0.825rem;
    font-weight: 600;
    color: var(--text-secondary);
    margin-bottom: 0.35rem;
}

.form-input {
    width: 100%;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.75rem 1rem;
    border-radius: var(--radius-sm);
    outline: none;
    transition: border-color 0.15s ease;
}

.form-input:focus {
    border-color: var(--accent-red);
}

/* Method Tabs */
.method-tabs {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.5rem;
    margin-bottom: 1.25rem;
}

.method-tab {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    padding: 0.65rem 0.5rem;
    border-radius: var(--radius-sm);
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
}

.method-tab.active {
    background-color: var(--accent-red-subtle);
    border-color: var(--accent-red);
    color: #ffffff;
}

.interface-box {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    padding: 1.25rem;
    border-radius: var(--radius-sm);
    margin-bottom: 1.25rem;
}

.demo-tag {
    display: inline-block;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.675rem;
    font-weight: 700;
    padding: 0.15rem 0.45rem;
    border-radius: var(--radius-sm);
    text-transform: uppercase;
    margin-bottom: 0.75rem;
}

.help-text {
    font-size: 0.775rem;
    color: var(--text-muted);
    margin-top: 0.5rem;
}

.test-card-preview {
    background: linear-gradient(135deg, #1f2937 0%, #111827 100%);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    padding: 1.25rem;
    color: #ffffff;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.mastercard-theme {
    background: linear-gradient(135deg, #374151 0%, #1f2937 100%);
}

.card-chip {
    width: 34px;
    height: 24px;
    background-color: #d97706;
    border-radius: 4px;
}

.card-number-display {
    font-family: monospace;
    font-size: 1.15rem;
    letter-spacing: 0.15em;
}

.card-details-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.75rem;
    color: var(--text-secondary);
}

.simulation-status-box {
    background-color: var(--bg-elevated);
    border: 1px solid var(--accent-red);
    padding: 1rem;
    border-radius: var(--radius-sm);
    margin-bottom: 1.25rem;
    text-align: center;
}

.status-spinner {
    width: 24px;
    height: 24px;
    border: 2px solid var(--border-color);
    border-top-color: var(--accent-red);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 0.5rem auto;
}

.simulation-step-text {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 0.5rem;
}

.progress-bar-track {
    width: 100%;
    height: 6px;
    background-color: var(--bg-surface);
    border-radius: 3px;
    overflow: hidden;
}

.progress-bar-fill {
    height: 100%;
    width: 0%;
    background-color: var(--accent-red);
    transition: width 0.4s ease;
}

.btn-checkout-submit {
    width: 100%;
    padding: 0.85rem;
    font-size: 1rem;
}

/* Main Container for Library */
.main-content {
    max-width: 1240px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    flex: 1;
}

/* Hero / Featured Section */
.hero-section {
    position: relative;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    padding: 2.25rem 2rem;
    margin-bottom: 2rem;
    overflow: hidden;
    background-image: linear-gradient(to right, rgba(24, 24, 28, 0.95) 45%, rgba(24, 24, 28, 0.65)), url('https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 620px;
}

.hero-tag-group {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 0.4rem;
}

.hero-tag {
    color: var(--accent-red);
    font-size: 0.725rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.tech-sample-pill {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.675rem;
    font-weight: 600;
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
}

.hero-title {
    font-size: 2.25rem;
    font-weight: 800;
    line-height: 1.15;
    margin-bottom: 0.4rem;
    letter-spacing: -0.025em;
}

.hero-meta {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-secondary);
    font-size: 0.85rem;
    margin-bottom: 0.85rem;
    flex-wrap: wrap;
}

.meta-tag {
    background-color: var(--accent-red-subtle);
    color: var(--accent-red);
    padding: 0.1rem 0.4rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.725rem;
}

.meta-separator {
    color: var(--text-muted);
}

.hero-description {
    color: var(--text-secondary);
    font-size: 0.925rem;
    margin-bottom: 1.25rem;
    line-height: 1.55;
}

.hero-actions {
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 1.1rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.875rem;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background-color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
    background-color: var(--accent-red);
    color: #ffffff;
}

.btn-primary:hover {
    background-color: var(--accent-red-hover);
}

.btn-secondary {
    background-color: var(--bg-elevated);
    color: var(--text-primary);
    border-color: var(--border-color);
}

.btn-secondary:hover {
    background-color: var(--bg-hover);
}

/* Catalogue Section */
.section-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 1rem;
}

.section-title {
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: -0.015em;
}

.item-count {
    color: var(--text-muted);
    font-size: 0.825rem;
}

.toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    padding: 0.75rem 1rem;
    border-radius: var(--radius-md);
    align-items: center;
    justify-content: space-between;
}

.search-box {
    position: relative;
    flex: 1;
    min-width: 250px;
    display: flex;
    align-items: center;
}

.search-icon {
    position: absolute;
    left: 0.75rem;
    font-size: 0.85rem;
    color: var(--text-muted);
    pointer-events: none;
}

.search-box input {
    width: 100%;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.5rem 2.2rem 0.5rem 2.2rem;
    border-radius: var(--radius-sm);
    outline: none;
    transition: border-color 0.15s ease;
}

.search-box input:focus {
    border-color: var(--border-focus);
}

.clear-btn {
    position: absolute;
    right: 0.6rem;
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 0.95rem;
    cursor: pointer;
}

.clear-btn:hover {
    color: var(--text-primary);
}

.filter-group {
    display: flex;
    gap: 0.75rem;
    align-items: center;
    flex-wrap: wrap;
}

.type-tabs {
    display: flex;
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    padding: 2px;
}

.type-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    padding: 0.35rem 0.85rem;
    border-radius: var(--radius-sm);
    font-size: 0.825rem;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease;
}

.type-tab.active {
    background-color: var(--bg-hover);
    color: var(--text-primary);
    font-weight: 600;
}

.select-wrapper select {
    background-color: var(--bg-elevated);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.4rem 0.85rem;
    border-radius: var(--radius-sm);
    outline: none;
    cursor: pointer;
    font-size: 0.825rem;
}

.select-wrapper select:focus {
    border-color: var(--border-focus);
}

/* UI States */
.state-view {
    text-align: center;
    padding: 3rem 1rem;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
}

.state-icon {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.state-view h3 {
    font-size: 1.05rem;
    margin-bottom: 0.3rem;
}

.state-view p {
    color: var(--text-secondary);
    font-size: 0.875rem;
    margin-bottom: 1rem;
}

.spinner {
    width: 32px;
    height: 32px;
    border: 3px solid var(--border-color);
    border-top-color: var(--accent-red);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 1rem auto;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Media Cards Grid */
.media-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
}

@media (max-width: 1199px) {
    .media-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 899px) {
    .media-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 599px) {
    .media-grid {
        grid-template-columns: repeat(1, 1fr);
    }
}

/* Media Card Styling */
.media-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    height: 100%;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.media-card:hover {
    transform: translateY(-2px);
    border-color: var(--text-muted);
}

.card-thumb-wrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    background-color: var(--bg-elevated);
    overflow: hidden;
    cursor: pointer;
}

.card-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.25s ease;
}

.card-thumb-wrapper:hover .card-thumb {
    transform: scale(1.04);
}

.card-badge {
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
    background-color: rgba(18, 18, 20, 0.9);
    border: 1px solid var(--border-color);
    color: var(--accent-red);
    font-size: 0.675rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.125rem 0.45rem;
    border-radius: var(--radius-sm);
    letter-spacing: 0.04em;
}

.tech-sample-tag {
    position: absolute;
    bottom: 0.5rem;
    right: 0.5rem;
    background-color: rgba(18, 18, 20, 0.85);
    border: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.625rem;
    padding: 0.1rem 0.35rem;
    border-radius: var(--radius-sm);
}

.card-content {
    padding: 0.95rem;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.card-title {
    font-size: 0.975rem;
    font-weight: 700;
    line-height: 1.35;
    margin-bottom: 0.25rem;
    color: var(--text-primary);
    cursor: pointer;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    max-height: 2.7em;
}

.card-title:hover {
    color: var(--accent-red);
}

.card-subtitle {
    color: var(--text-secondary);
    font-size: 0.825rem;
    margin-bottom: 0.4rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.card-meta {
    display: flex;
    gap: 0.4rem;
    align-items: center;
    color: var(--text-muted);
    font-size: 0.775rem;
    margin-bottom: 0.85rem;
}

.card-actions {
    margin-top: auto;
    display: flex;
    gap: 0.4rem;
}

.card-actions .btn {
    flex: 1;
    padding: 0.4rem 0.5rem;
    font-size: 0.8rem;
}

/* Application Footer */
.app-footer {
    background-color: var(--bg-surface);
    border-top: 1px solid var(--border-color);
    padding: 1.5rem;
    margin-top: auto;
}

.footer-container {
    max-width: 1240px;
    margin: 0 auto;
