    flex-direction: column;
    gap: 0.5rem;
}

.footer-brand {
    font-weight: 700;
    font-size: 0.9rem;
    color: var(--text-primary);
}

.footer-disclaimer {
    color: var(--text-muted);
    font-size: 0.775rem;
    line-height: 1.5;
}

/* Details Dialog Modal */
.details-dialog {
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
